import { SubjectLessonMatrix } from './types';

export const CONTABILIDADE_LESSON_MATRIX: SubjectLessonMatrix = {
  0: [
    { sub: 'Conceito, Objeto e Finalidade da Contabilidade', ref: 'Doutrina Contábil e CPC 00', t: 'O objeto da Contabilidade é o patrimônio das entidades econômico-administrativas, enquanto sua finalidade precípua é fornecer informações úteis aos diversos usuários para a tomada de decisões.', f: 'O objeto da Contabilidade restringe-se ao lucro tributável das sociedades empresárias, excluindo-se as entidades sem fins lucrativos do campo de aplicação contábil.', exp: 'Objeto = Patrimônio; Finalidade = controle e planejamento (fornecer informações para decisão).' },
    { sub: 'Técnicas Contábeis', ref: 'Teoria da Contabilidade', t: 'São quatro as técnicas contábeis clássicas utilizadas para alcançar a finalidade da ciência contábil: escrituração, demonstrações contábeis, auditoria e análise das demonstrações contábeis (análise de balanços).', f: 'O planejamento tributário e a perícia judicial constituem as duas únicas técnicas contábeis reconhecidas pela estrutura conceitual básica.', exp: 'As 4 técnicas contábeis são: Escrituração, Demonstrações, Auditoria e Análise de Balanços.' },
    { sub: 'Campo de Aplicação (Aziendas)', ref: 'Doutrina Clássica', t: 'A Contabilidade aplica-se às aziendas (entidades econômico-administrativas), sejam elas de fins lucrativos (empresas) ou de fins ideais/sociais.', f: 'As entidades de fins meramente sociais ou filantrópicos são dispensadas de escrituração contábil por não possuírem patrimônio próprio.', exp: 'Azienda = gestão + patrimônio, abrangendo entidades públicas, privadas e do terceiro setor.' },
    { sub: 'Usuários Internos e Externos', ref: 'CPC 00 (R2)', t: 'Investidores existentes e em potencial, credores por empréstimos e outros credores constituem os usuários primários aos quais se destinam os relatórios financeiros para fins gerais.', f: 'Os relatórios contábeis para fins gerais são elaborados prioritariamente para atender às demandas exclusivas do Fisco e dos administradores internos.', exp: 'CPC 00: usuários primários são investidores, financiadores e outros credores externos.' },
    { sub: 'Regime de Competência vs. Caixa', ref: 'Lei 6.404/76, Art. 177', t: 'Pelo regime de competência, as receitas e as despesas são reconhecidas no período em que ocorrem os respectivos fatos geradores, independentemente do efetivo recebimento ou pagamento em moeda.', f: 'Na contabilidade societária brasileira, as companhias abertas devem apurar o resultado do exercício pelo regime de caixa para fins de distribuição de dividendos.', exp: 'O regime de competência (accrual basis) é obrigatório na escrituração mercantil (Art. 177 da LSA).' }
  ],
  1: [
    { sub: 'Equação Fundamental do Patrimônio', ref: 'Lei 6.404/76', t: 'A equação fundamental da contabilidade estabelece que o Situação Líquida (Patrimônio Líquido) corresponde à diferença algébrica entre o Ativo (bens e direitos) e o Passivo Exigível (obrigações com terceiros).', f: 'O Patrimônio Líquido representa a soma aritmética entre os bens tangíveis da entidade e o total de suas obrigações exigíveis a longo prazo.', exp: 'Ativo = Passivo Exigível + Patrimônio Líquido (A - PE = PL).' },
    { sub: 'Situação Líquida Nula ou Compensada', ref: 'Teoria Patrimonial', t: 'Configura-se a situação líquida nula, inexistente ou compensada quando o montante total do Ativo é exatamente igual ao montante do Passivo Exigível, resultando em Patrimônio Líquido igual a zero.', f: 'Na situação líquida compensada, o capital próprio supera o capital de terceiros na exata proporção do ativo imobilizado.', exp: 'Quando A = PE, temos PL = 0 (situação líquida nula ou compensada).' },
    { sub: 'Passivo a Descoberto', ref: 'Teoria Patrimonial', t: 'Ocorre passivo a descoberto (situação líquida negativa ou deficitária) quando o Passivo Exigível supera o Ativo Total da entidade, evidenciando que as obrigações com terceiros ultrapassam os bens e direitos.', f: 'O passivo a descoberto ocorre sempre que o saldo da conta Caixa é inferior ao saldo de Fornecedores de curto prazo.', exp: 'Passivo a descoberto: A < PE, logo PL < 0.' },
    { sub: 'Capital Próprio e Capital de Terceiros', ref: 'Doutrina Contábil', t: 'O Passivo Exigível representa as origens de recursos provenientes de terceiros (capital alheio), enquanto o Patrimônio Líquido representa os recursos próprios dos sócios ou acionistas.', f: 'O Ativo Circulante representa a origem dos recursos próprios, enquanto o Patrimônio Líquido representa a aplicação de recursos em bens de giro.', exp: 'Passivo + PL = Origens de recursos; Ativo = Aplicações de recursos.' },
    { sub: 'Capital Total à Disposição da Entidade', ref: 'Doutrina Contábil', t: 'O capital total à disposição da entidade corresponde à soma do capital próprio (Patrimônio Líquido) com o capital de terceiros (Passivo Exigível), equivalendo ao Ativo Total.', f: 'O capital total à disposição da empresa equivale exclusivamente ao capital social subscrito e integralizado no contrato social.', exp: 'Capital Total à Disposição = Passivo Exigível + PL = Ativo Total.' }
  ],
  2: [
    { sub: 'Fatos Contábeis Permutativos', ref: 'Doutrina Contábil', t: 'Os fatos contábeis permutativos (qualitativos ou compensativos) promovem trocas entre elementos patrimoniais (Ativo e/ou Passivo) sem alterar o valor total do Patrimônio Líquido.', f: 'A compra de mercadorias a prazo é um fato modificativo diminutivo, pois reduz imediatamente o Patrimônio Líquido da entidade compradora.', exp: 'Compra de mercadorias a prazo (+Ativo Estoques, +Passivo Fornecedores) é fato permutativo.' },
    { sub: 'Fatos Contábeis Modificativos', ref: 'Doutrina Contábil', t: 'Os fatos modificativos (quantitativos) provocam variação no valor do Patrimônio Líquido, podendo ser aumentativos (receitas) ou diminutivos (despesas).', f: 'O recebimento de duplicatas de clientes sem juros nem descontos configura fato contábil modificativo aumentativo.', exp: 'Recebimento sem juros é permutativo (+Caixa, -Clientes); fatos modificativos alteram o PL.' },
    { sub: 'Fatos Contábeis Mistos', ref: 'Doutrina Contábil', t: 'O fato contábil misto (ou composto) combina simultaneamente uma permuta entre elementos patrimoniais e uma alteração positiva ou negativa no Patrimônio Líquido, como na quitação de obrigação com desconto ou juros.', f: 'O pagamento de uma dívida em atraso acrescida de juros de mora classifica-se como fato meramente permutativo entre Caixa e Fornecedores.', exp: 'Quitação com juros é fato misto diminutivo; quitação com desconto obtido é fato misto aumentativo.' },
    { sub: 'Fórmulas de Lançamento (1ª a 4ª)', ref: 'Método das Partidas Dobradas', t: 'No método das partidas dobradas, o lançamento de 2ª fórmula (composto) apresenta uma única conta debitada e duas ou mais contas creditadas (1D / 2+C).', f: 'O lançamento de 3ª fórmula caracteriza-se por apresentar duas ou mais contas debitadas e duas ou mais contas creditadas simultaneamente.', exp: '1ª fórmula = 1D/1C; 2ª fórmula = 1D/N C; 3ª fórmula = N D/1C; 4ª fórmula = N D/N C.' },
    { sub: 'Atos Administrativos vs. Fatos Contábeis', ref: 'Teoria da Escrituração', t: 'Os atos administrativos não provocam alteração imediata no patrimônio da entidade, mas aqueles que puderem gerar efeitos futuros relevantes (como fianças e avais) são registrados em contas de compensação ou notas explicativas.', f: 'Todo ato administrativo assinado pela diretoria deve ser contabilizado a débito de despesa operacional no momento da assinatura.', exp: 'Atos não alteram o patrimônio imediatamente; fatos contábeis alteram qualitativa ou quantitativamente.' }
  ],
  3: [
    { sub: 'Teoria Materialista e Patrimonialista das Contas', ref: 'Teoria das Contas', t: 'Pela Teoria Patrimonialista (Vincenzo Masi), as contas dividem-se em dois grandes grupos: Contas Patrimoniais (Ativo, Passivo e Patrimônio Líquido) e Contas de Resultado (Receitas e Despesas).', f: 'Pela Teoria Personalista, todas as contas de despesas e receitas são classificadas como contas dos agentes consignatários.', exp: 'Teoria Patrimonialista (adotada no Brasil): Contas Patrimoniais vs. Contas de Resultado.' },
    { sub: 'Natureza das Contas e Mecanismo de Débito/Crédito', ref: 'Escrituração Contábil', t: 'As contas de Ativo e de Despesas possuem natureza devedora (aumentam por débito), ao passo que as contas de Passivo, Patrimônio Líquido e Receitas possuem natureza credora (aumentam por crédito).', f: 'As contas de Receitas aumentam por lançamentos a débito porque representam entrada de recursos financeiros no caixa.', exp: 'Aplicações (Ativo/Despesa) = natureza devedora; Origens (Passivo/PL/Receita) = natureza credora.' },
    { sub: 'Contas Retificadoras', ref: 'Lei 6.404/76', t: 'As contas retificadoras possuem natureza inversa à do grupo a que pertencem: retificadoras do Ativo (como Depreciação Acumulada e PCLD) têm saldo credor, enquanto retificadoras do Passivo/PL (como Ações em Tesouraria) têm saldo devedor.', f: 'A conta Depreciação Acumulada possui natureza devedora por integrar o subgrupo do Ativo Não Circulante Imobilizado.', exp: 'Retificadora de Ativo = natureza credora; Retificadora de Passivo/PL = natureza devedora.' },
    { sub: 'Plano de Contas e Grau de Detalhamento', ref: 'ITG 2000', t: 'No plano de contas, as contas sintéticas (de 1º, 2º ou 3º grau) totalizam os saldos de um grupo, enquanto apenas as contas analíticas (de último nível) recebem diretamente os lançamentos contábeis de débito e crédito.', f: 'Os lançamentos de diário devem ser efetuados diretamente nas contas sintéticas de primeiro grau do Balanço Patrimonial.', exp: 'Apenas as contas analíticas recebem escrituração direta; as sintéticas são totalizadoras.' },
    { sub: 'Livros Contábeis: Diário e Razão', ref: 'Código Civil e ITG 2000', t: 'O Livro Diário registra os fatos em ordem estritamente cronológica (dia, mês e ano), enquanto o Livro Razão agrupa os lançamentos de forma sistemática por conta contábil para controle individualizado dos saldos.', f: 'O Livro Razão é facultativo para as empresas tributadas pelo lucro real, bastando a escrituração resumida do Livro Caixa.', exp: 'Diário (cronológico) e Razão (sistemático) são livros obrigatórios segundo a ITG 2000 e legislação.' }
  ],
  4: [
    { sub: 'Finalidade do Balancete de Verificação', ref: 'ITG 2000 / Doutrina', t: 'O balancete de verificação tem por finalidade demonstrar a igualdade matemática entre o total dos débitos e o total dos créditos escriturados no Razão, decorrente do método das partidas dobradas.', f: 'O balancete de verificação é uma demonstração financeira obrigatória que deve ser publicada anualmente no Diário Oficial.', exp: 'O balancete é um demonstrativo auxiliar interno (não obrigatório para publicação) de verificação.' },
    { sub: 'Limitações do Balancete na Detecção de Erros', ref: 'Doutrina Contábil', t: 'O fechamento do balancete (total de saldos devedores igual ao total de saldos credores) não garante a ausência de erros de inversão de contas, de classificação indevida ou de omissão completa de um lançamento.', f: 'Se a soma dos saldos devedores igualar a soma dos saldos credores no balancete, fica comprovada a inexistência de qualquer erro de escrituração.', exp: 'Lançar valor correto em conta errada da mesma natureza ou omitir partida inteira não quebra a igualdade.' },
    { sub: 'Colunas do Balancete (2, 4, 6 e 8 colunas)', ref: 'Técnica Contábil', t: 'Um balancete de verificação pode ser levantado com 2 colunas (apenas saldos finais devedores e credores), 4, 6 ou até 8 colunas (evidenciando saldos iniciais, movimentos do período e saldos finais).', f: 'A norma brasileira de contabilidade proíbe o levantamento de balancetes com mais de duas colunas de saldos.', exp: 'Balancetes podem ter 2, 4, 6 ou 8 colunas conforme o nível de detalhe do movimento do período.' },
    { sub: 'Contas Presentes no Balancete Pré-Encerramento', ref: 'Técnica Contábil', t: 'No balancete de verificação levantado antes da apuração do resultado do exercício (pré-ARE), figuram conjuntamente todas as contas patrimoniais e todas as contas de resultado (receitas e despesas) com saldo.', f: 'As contas de receitas e despesas jamais transitam pelo balancete de verificação, figurando apenas diretamente na DRE.', exp: 'Antes do encerramento (ARE), tanto contas patrimoniais quanto de resultado constam no balancete.' },
    { sub: 'Balancete Pós-Encerramento', ref: 'Técnica Contábil', t: 'No balancete de verificação levantado imediatamente após o encerramento das contas de resultado (pós-ARE), permanecem com saldo exclusivamente as contas patrimoniais (Ativo, Passivo e Patrimônio Líquido).', f: 'No balancete pós-encerramento, as contas de despesas operacionais permanecem abertas para transferência ao exercício seguinte.', exp: 'Na ARE, receitas e despesas são zeradas contra Resultado do Exercício, restando só contas patrimoniais.' }
  ],
  5: [
    { sub: 'Características Qualitativas Fundamentais', ref: 'CPC 00 (R2)', t: 'Segundo o CPC 00 (R2), as características qualitativas fundamentais da informação financeira útil são a Relevância (incluindo a materialidade) e a Representação Fidedigna (completa, neutra e isenta de erros).', f: 'A comparabilidade e a tempestividade são as duas únicas características qualitativas fundamentais definidas pelo CPC 00 (R2).', exp: 'Fundamentais = Relevância + Representação Fidedigna. De melhoria = Comparabilidade, Verificabilidade, Tempestividade e Compreensibilidade.' },
    { sub: 'Prudência e Neutralidade', ref: 'CPC 00 (R2)', t: 'A representação fidedigna exige neutralidade, que é apoiada pelo exercício da prudência (cautela ao fazer julgamentos sob condições de incerteza, sem superavaliar ativos/receitas nem subavaliar passivos/despesas).', f: 'O exercício da prudência no CPC 00 (R2) autoriza a constituição deliberada de reservas ocultas mediante a subavaliação sistemática de ativos.', exp: 'Prudência apoia a neutralidade e não permite subavaliação deliberada (assimetria injustificada).' },
    { sub: 'Características Qualitativas de Melhoria', ref: 'CPC 00 (R2)', t: 'Comparabilidade, verificabilidade, tempestividade e compreensibilidade são características qualitativas de melhoria que ampliam a utilidade da informação relevante e representada de forma fidedigna.', f: 'A essência sobre a forma e a materialidade classificam-se como características qualitativas de melhoria no CPC 00 (R2).', exp: 'Sigla CVTC: Comparabilidade, Verificabilidade, Tempestividade e Compreensibilidade.' },
    { sub: 'Definição de Ativo no CPC 00 (R2)', ref: 'CPC 00 (R2), item 4.3', t: 'Ativo é um recurso econômico presente controlado pela entidade como resultado de eventos passados, sendo recurso econômico um direito que tem o potencial de produzir benefícios econômicos.', f: 'Para que um item seja reconhecido como Ativo pelo CPC 00 (R2), é indispensável a propriedade jurídica formal do bem e a certeza absoluta de entrada de caixa.', exp: 'Não se exige propriedade jurídica (basta o controle do direito) nem certeza (basta potencial).' },
    { sub: 'Definição de Passivo no CPC 00 (R2)', ref: 'CPC 00 (R2), item 4.26', t: 'Passivo é uma obrigação presente da entidade de transferir um recurso econômico como resultado de eventos passados, exigindo que a entidade não tenha capacidade prática de evitar a transferência.', f: 'A mera intenção futura da administração de adquirir um equipamento no próximo ano já constitui passivo exigível na data do balanço.', exp: 'Passivo exige: (1) obrigação presente; (2) de transferir recurso econômico; (3) resultante de evento passado.' }
  ],
  6: [
    { sub: 'Mensuração dos Estoques', ref: 'CPC 16 (R1)', t: 'Os estoques devem ser mensurados pelo valor de custo ou pelo valor realizável líquido, dos dois o menor.', f: 'Os estoques de mercadorias para revenda devem ser avaliados sempre pelo valor justo de mercado acrescido da margem de lucro esperada.', exp: 'Regra de ouro do CPC 16: Custo ou Valor Realizável Líquido, dos dois o menor.' },
    { sub: 'Itens Incluídos e Excluídos do Custo dos Estoques', ref: 'CPC 16 (R1)', t: 'O custo de aquisição dos estoques compreende o preço de compra, os impostos de importação, os tributos não recuperáveis, o frete sobre compras e o seguro no transporte até o estabelecimento comprador.', f: 'As despesas de comercialização, o frete sobre vendas e os tributos recuperáveis (como ICMS recuperável) integram o custo de aquisição dos estoques.', exp: 'Fretes sobre compras e tributos não recuperáveis entram no estoque; frete sobre vendas é despesa comercial.' },
    { sub: 'Critérios de Valoração: PEPS, Média Ponderada e UEPS', ref: 'CPC 16 e RIR', t: 'O CPC 16 admite o uso do custo específico, do PEPS (Primeiro a Entrar, Primeiro a Sair) e da Média Ponderada Móvel, vedando a adoção do método UEPS (Último a Entrar, Primeiro a Sair).', f: 'Em cenários inflacionários, o método PEPS proporciona o maior Custo das Mercadorias Vendidas (CMV) e o menor Lucro Bruto.', exp: 'Em inflação, PEPS gera menor CMV e maior Estoque Final/Lucro Bruto; o UEPS é vedado pelo CPC 16 e pelo Fisco.' },
    { sub: 'Fórmula do CMV no Inventário Periódico', ref: 'Técnica Contábil', t: 'No sistema de inventário periódico, o Custo das Mercadorias Vendidas é apurado pela fórmula: CMV = Estoque Inicial + Compras Líquidas - Estoque Final.', f: 'No inventário periódico, as devoluções de compras e os abatimentos sobre compras são somados às compras brutas para aumentar o CMV.', exp: 'Compras Líquidas = Compras Brutas + Frete/Seguro s/ compras - Devoluções - Abatimentos - Descontos Incondicionais - Tributos Recuperáveis.' },
    { sub: 'Descontos Incondicionais vs. Condicionais', ref: 'CPC 16 / CPC 47', t: 'Os descontos incondicionais (comerciais) obtidos na nota fiscal reduzem o custo de aquisição do estoque, enquanto os descontos condicionais (financeiros) obtidos no pagamento antecipado da duplicata constituem receita financeira.', f: 'Tanto os descontos comerciais quanto os descontos financeiros obtidos reduzem diretamente o saldo da conta Estoques.', exp: 'Desconto incondicional = deduz compra/venda; Desconto condicional = receita/despesa financeira.' }
  ],
  7: [
    { sub: 'Regra de Recuperabilidade dos Tributos', ref: 'CPC 16 / Legislação Tributária', t: 'Os tributos recuperáveis (não cumulativos, quando dão direito a crédito) são segregados do custo de aquisição do estoque e registrados no Ativo Circulante como Tributos a Recuperar.', f: 'Os tributos não recuperáveis pagos na aquisição de mercadorias são lançados diretamente como despesa financeira na DRE do mês da compra.', exp: 'Recuperáveis -> Ativo (Tributos a Recuperar); Não recuperáveis -> integram o custo do bem adquirido.' },
    { sub: 'IPI na Compra por Empresa Comercial vs. Industrial', ref: 'Legislação do IPI / Contabilidade', t: 'Quando uma empresa estritamente comercial (não contribuinte do IPI) adquire mercadorias para revenda, o IPI destacado na nota de compra não é recuperável e, portanto, integra o custo de aquisição dos estoques e a base do ICMS.', f: 'A empresa meramente varejista recupera integralmente o IPI pago nas compras de mercadorias mediante crédito fiscal.', exp: 'Comerciante puro não é contribuinte habitual de IPI, logo o IPI na compra é não recuperável e entra no custo.' },
    { sub: 'ICMS por Dentro e Base de Cálculo', ref: 'LC 87/96 / Contabilidade', t: 'O ICMS é calculado "por dentro", de modo que seu valor já está embutido no preço bruto da mercadoria, ao passo que o IPI é calculado "por fora", sendo somado ao valor dos produtos para compor o total da nota fiscal.', f: 'O ICMS é sempre somado por fora ao valor líquido da nota fiscal, não compondo sua própria base de cálculo.', exp: 'ICMS incide por dentro (integra o preço do produto); IPI incide por fora.' },
    { sub: 'PIS e COFINS Não Cumulativos sobre Estoques', ref: 'Leis 10.637/02 e 10.833/03', t: 'No regime não cumulativo de PIS e COFINS (alíquotas gerais de 1,65% e 7,6%), os créditos permitidos sobre compras de mercadorias para revenda reduzem o custo de aquisição dos estoques.', f: 'No regime cumulativo de PIS e COFINS, a empresa comercial apropria créditos de 9,25% sobre todas as compras de mercadorias.', exp: 'No regime cumulativo (0,65% e 3%) não há crédito sobre compras; no não cumulativo (1,65% e 7,6%) há recuperação.' },
    { sub: 'Apuração Mensal de ICMS a Recolher ou a Recuperar', ref: 'Técnica Contábil', t: 'Ao final do período de apuração, confrontam-se os saldos de ICMS a Recuperar (Ativo) e ICMS a Recolher (Passivo): se o passivo for maior, resta obrigação líquida a pagar; se o ativo for maior, permanece saldo credor fiscal a compensar.', f: 'Os saldos de ICMS a Recuperar e ICMS a Recolher nunca se compensam, devendo permanecer acumulados indefinidamente no Balanço.', exp: 'A apuração contábil compensa a conta de menor saldo contra a de maior saldo ao fim do mês.' }
  ],
  8: [
    { sub: 'Classificação das Duplicatas Descontadas', ref: 'CPC 48 / Lei 6.404/76', t: 'As Duplicatas Descontadas com direito de regresso (coobrigação da empresa cedente) são classificadas no Passivo Exigível como obrigação por empréstimo garantido, vez que os riscos de inadimplência não foram transferidos.', f: 'As Duplicatas Descontadas são classificadas como conta retificadora do Patrimônio Líquido.', exp: 'Desde a convergência às IFRS (CPC 38/48), duplicata descontada com coobrigação é Passivo Exigível.' },
    { sub: 'Encargos Financeiros no Desconto de Duplicatas', ref: 'Regime de Competência', t: 'Os juros e encargos bancários cobrados antecipadamente no desconto de duplicatas são registrados em conta de Encargos Financeiros a Transcorrer (retificadora do Passivo) e apropriados à DRE pro rata temporis pelo regime de competência.', f: 'Os juros descontados pelo banco na operação de duplicatas descontadas são reconhecidos integralmente como receita operacional no ato da contratação.', exp: 'Encargos descontados na largada ficam em Encargos a Transcorrer (retificadora do passivo) e viram despesa pelo tempo.' },
    { sub: 'Liquidação ou Inadimplência da Duplicata Descontada', ref: 'Técnica Contábil', t: 'Se o cliente quitar a duplicata descontada no vencimento, a empresa baixa simultaneamente a conta Clientes (Ativo) e a conta Duplicatas Descontadas (Passivo); se houver inadimplência, o banco debita a conta corrente da empresa.', f: 'Quando o cliente paga a duplicata descontada ao banco, a empresa cedente registra um novo ingresso de dinheiro em sua conta Bancos.', exp: 'O dinheiro já entrou no ato do desconto; na quitação pelo cliente, baixa-se Duplicatas Descontadas contra Clientes.' },
    { sub: 'Perdas Estimadas em Créditos de Liquidação Duvidosa (PCLD)', ref: 'CPC 48', t: 'A PCLD é uma conta retificadora do Ativo (natureza credora) que reduz o valor contábil das Contas a Receber ao valor que se espera efetivamente recuperar, sendo constituída a débito de Despesa com PCLD na DRE.', f: 'A constituição da PCLD é contabilizada a débito de Clientes e a crédito de Receita Financeira.', exp: 'Constituição de PCLD: D - Despesa com PCLD (DRE) / C - PCLD (Retificadora do Ativo).' },
    { sub: 'Baixa de Créditos Incobráveis e Recuperação', ref: 'Técnica Contábil', t: 'Quando um título anteriormente provisionado torna-se definitivamente incobrável, sua baixa é feita debitando-se a conta PCLD e creditando-se Clientes (fato permutativo entre contas do Ativo, sem novo impacto no resultado).', f: 'A baixa definitiva de um cliente incobrável até o limite da PCLD constituída gera uma segunda despesa operacional na DRE.', exp: 'D - PCLD / C - Clientes: não afeta o resultado nem o total do Ativo Líquido no momento da baixa.' }
  ],
  9: [
    { sub: 'Conceito e Reconhecimento do Ativo Imobilizado', ref: 'CPC 27', t: 'Ativo imobilizado é o item tangível mantido para uso na produção ou fornecimento de mercadorias ou serviços, para aluguel a outros, ou para fins administrativos, e que se espera utilizar por mais de um período.', f: 'Imóveis mantidos exclusivamente para valorização de capital a longo prazo ou vendidos no curso normal dos negócios classificam-se no Ativo Imobilizado.', exp: 'Imóvel para valorização/renda sem uso na atividade = Propriedade para Investimento (CPC 28); para venda = Estoque (CPC 16).' },
    { sub: 'Composição do Custo Inicial do Imobilizado', ref: 'CPC 27', t: 'Integram o custo do ativo imobilizado o preço de aquisição (acrescido de impostos não recuperáveis), os custos diretamente atribuíveis para colocá-lo no local e condição de funcionamento, e a estimativa inicial de custos de desmontagem e remoção.', f: 'Os gastos com treinamento da equipe para operar a nova máquina e os custos de inauguração de nova instalação integram o custo contábil do Imobilizado.', exp: 'Treinamento de pessoal, propaganda e custos de abertura de nova instalação são despesas do período (vedada ativação).' },
    { sub: 'Cessação da Capitalização de Custos', ref: 'CPC 27, item 20', t: 'O reconhecimento dos custos no valor contábil de um item do ativo imobilizado cessa quando o item está no local e nas condições operacionais pretendidas pela administração, ainda que não esteja operando a plena capacidade.', f: 'Os prejuízos operacionais iniciais incorridos enquanto a demanda pelo produto da máquina ainda está crescendo devem ser capitalizados no Imobilizado.', exp: 'Assim que o ativo está pronto para operar, cessa a ativação de custos; perdas operacionais iniciais vão para a DRE.' },
    { sub: 'Mensuração Subsequente e Vedação à Reavaliação', ref: 'Lei 6.404/76 e CPC 27', t: 'No Brasil, por força da Lei nº 11.638/2007, é vedada a reavaliação espontânea de bens do ativo imobilizado ao valor justo, devendo ser adotado o método do custo (custo menos depreciação acumulada e perdas por impairment).', f: 'As companhias brasileiras podem reavaliar anualmente seus imóveis operacionais a valor de mercado, lançando o ganho em Reserva de Reavaliação.', exp: 'A Reserva de Reavaliação de ativos próprios foi extinta pela Lei 11.638/07.' },
    { sub: 'Peças de Reposição e Paradas Programadas', ref: 'CPC 27', t: 'Peças de reposição principais, equipamentos de reserva com vida útil superior a um período e gastos com grandes inspeções periódicas obrigatórias são reconhecidos no Ativo Imobilizado, baixando-se o valor contábil das peças substituídas.', f: 'Os gastos com manutenção diária, lubrificação e pequenos reparos de rotina devem ser obrigatoriamente capitalizados no Imobilizado.', exp: 'Manutenção rotineira é despesa na DRE; grandes paradas/substituições que aumentam vida útil são ativadas.' }
  ],
  10: [
    { sub: 'Início e Cessação da Depreciação', ref: 'CPC 27, item 55', t: 'A depreciação de um ativo começa quando ele está disponível para uso (no local e condição de funcionamento pretendidos) e cessa na data em que o ativo é classificado como mantido para venda ou baixado, o que ocorrer primeiro.', f: 'A depreciação somente se inicia quando o bem entra efetivamente em operação comercial e é suspensa sempre que a máquina fica ociosa.', exp: 'A depreciação começa quando disponível para uso e NÃO cessa quando o ativo se torna ocioso (salvo pelo método de unidades produzidas).' },
    { sub: 'Valor Depreciável e Valor Residual', ref: 'CPC 27', t: 'O valor depreciável de um ativo é determinado após a dedução de seu valor residual estimado: Valor Depreciável = Custo de Aquisição - Valor Residual.', f: 'O valor residual é somado ao custo de aquisição para ampliar a base de cálculo da despesa anual de depreciação.', exp: 'Base de depreciação (valor depreciável) = Custo - Valor Residual. Se Valor Residual > Valor Contábil, a depreciação é zero.' },
    { sub: 'Métodos de Depreciação (Linear, Soma dos Dígitos e Unidades)', ref: 'CPC 27', t: 'Pelo método da soma dos dígitos dos anos (Cole) decrescente, as quotas de depreciação são maiores nos primeiros anos de vida útil e menores nos últimos anos.', f: 'No método linear (quotas constantes), a despesa de depreciação dobra a cada exercício social até o esgotamento do bem.', exp: 'Linear = quotas iguais; Cole decrescente = quotas decrescentes; Unidades produzidas = proporcional à produção.' },
    { sub: 'Amortização e Exaustão', ref: 'Lei 6.404/76, Art. 183, §2º', t: 'A amortização corresponde à perda do valor do capital aplicado na aquisição de direitos da propriedade industrial/comercial ou intangíveis com prazo limitado, enquanto a exaustão aplica-se à exploração de recursos naturais (minerais e florestais).', f: 'Os terrenos rurais e urbanos sofrem exaustão linear obrigatória à taxa de 4% ao ano.', exp: 'Depreciação = bens tangíveis; Amortização = intangíveis/direitos; Exaustão = recursos minerais/florestais. Terrenos em regra não depreciam.' },
    { sub: 'Revisão de Vida Útil e Valor Residual (Estimativa Contábil)', ref: 'CPC 27 e CPC 23', t: 'O valor residual e a vida útil de um ativo devem ser revisados pelo menos ao final de cada exercício, e eventuais alterações são contabilizadas prospectivamente como mudança de estimativa contábil (CPC 23).', f: 'A alteração da vida útil estimada de um veículo exige a reapresentação retrospectiva de todos os balanços dos últimos cinco anos.', exp: 'Mudança de vida útil ou método de depreciação é mudança de estimativa contábil -> efeito prospectivo.' }
  ],
  11: [
    { sub: 'Definição e Critérios do Ativo Intangível', ref: 'CPC 04 (R1)', t: 'Ativo intangível é um ativo não monetário identificável sem substância física; para ser identificável, deve ser separável (negociável separadamente) ou resultar de direitos contratuais ou outros direitos legais.', f: 'A carteira de clientes fidelizados sem contrato e a boa reputação geral da equipe são reconhecidas como Ativo Intangível gerado internamente.', exp: 'Para ser Intangível (CPC 04): não monetário, sem substância física, identificável (separável ou contratual/legal) e controlado.' },
    { sub: 'Goodwill Gerado Internamente', ref: 'CPC 04 (R1), item 48', t: 'O ágio derivado da expectativa de rentabilidade futura (goodwill) gerado internamente não deve ser reconhecido como ativo, pois não é um recurso identificável controlado que possa ser mensurado com confiabilidade ao custo.', f: 'O goodwill gerado internamente pela valorização da marca própria no mercado deve ser ativado anualmente em contrapartida ao Patrimônio Líquido.', exp: 'Goodwill interno, marcas, títulos de publicações e listas de clientes gerados internamente NUNCA são ativados.' },
    { sub: 'Fase de Pesquisa vs. Fase de Desenvolvimento', ref: 'CPC 04 (R1), itens 54-57', t: 'Os gastos incorridos na fase de pesquisa de projeto interno devem ser reconhecidos sempre como despesa quando incorridos, enquanto os gastos na fase de desenvolvimento são ativados se (e somente se) demonstrada a viabilidade técnica e econômica.', f: 'Todos os gastos da fase de pesquisa científica preliminar devem ser capitalizados no Ativo Intangível para amortização em dez anos.', exp: 'Pesquisa = sempre Despesa na DRE; Desenvolvimento = Ativo Intangível (se atendidos os 6 requisitos de viabilidade do CPC 04).' },
    { sub: 'Intangível com Vida Útil Definida vs. Indefinida', ref: 'CPC 04 (R1)', t: 'Um ativo intangível com vida útil definida é amortizado ao longo dessa vida, já o intangível com vida útil indefinida não deve ser amortizado, mas submetido ao teste de recuperabilidade (impairment) anualmente e sempre que houver indício.', f: 'Os ativos intangíveis com vida útil indefinida são amortizados obrigatoriamente pelo prazo máximo legal de vinte anos.', exp: 'Vida útil definida -> amortiza; Vida útil indefinida -> NÃO amortiza, mas testa impairment no mínimo anualmente.' },
    { sub: 'Valor Residual do Intangível com Vida Definida', ref: 'CPC 04 (R1), item 100', t: 'Presume-se que o valor residual de um ativo intangível com vida útil definida seja zero, a menos que haja compromisso de terceiro para comprá-lo ao final da vida útil ou exista mercado ativo para ele.', f: 'Todo ativo intangível possui obrigatoriamente valor residual mínimo equivalente a 20% do seu custo histórico.', exp: 'Regra geral no CPC 04: valor residual do intangível é ZERO, salvo compromisso firme de compra ou mercado ativo.' }
  ],
  12: [
    { sub: 'Conceito de Valor Recuperável', ref: 'CPC 01 (R1)', t: 'O valor recuperável de um ativo ou de uma unidade geradora de caixa é definido como o maior montante entre o seu valor justo líquido de despesas de venda e o seu valor em uso.', f: 'O valor recuperável corresponde à média aritmética simples entre o custo histórico de aquisição e o valor residual contábil.', exp: 'Valor Recuperável = MAIOR entre (Valor Justo Líquido de Despesa de Venda) e (Valor em Uso).' },
    { sub: 'Reconhecimento da Perda por Desvalorização (Impairment)', ref: 'CPC 01 (R1)', t: 'Se, e somente se, o valor recuperável de um ativo for inferior ao seu valor contábil líquido, o valor contábil deve ser reduzido ao seu valor recuperável, reconhecendo-se uma perda por desvalorização na DRE (em regra).', f: 'Quando o valor recuperável supera o valor contábil do ativo imobilizado, a entidade deve registrar um ganho imediato na DRE até o limite do valor de mercado.', exp: 'Se Valor Contábil > Valor Recuperável -> reconhece perda por impairment. Se Valor Recuperável > Valor Contábil -> nada se faz (salvo reversão).' },
    { sub: 'Ativos Testados Anualmente Independentemente de Indícios', ref: 'CPC 01 (R1), item 10', t: 'Independentemente da existência de qualquer indicação de desvalorização, a entidade deve testar no mínimo anualmente o intangível com vida útil indefinida, o intangível ainda não disponível para uso e o ágio por rentabilidade futura (goodwill).', f: 'Todos os veículos e computadores do Ativo Imobilizado exigem cálculo atuarial anual de valor em uso, mesmo sem qualquer indício de perda.', exp: 'Para imobilizado e intangível de vida definida, avalia-se se há indícios; para intangível indefinido, em andamento e goodwill, o teste anual é obrigatório.' },
    { sub: 'Reversão de Perda por Impairment', ref: 'CPC 01 (R1)', t: 'A reversão de uma perda por desvalorização reconhecida em períodos anteriores é permitida para ativos em geral (limitada ao valor contábil que teria se não houvesse perda), mas é expressamente proibida para o goodwill.', f: 'A perda por desvalorização reconhecida sobre o goodwill em uma combinação de negócios deve ser revertida no ano seguinte caso o lucro da controlada aumente.', exp: 'Impairment de Goodwill NUNCA pode ser revertido (CPC 01, item 124).' },
    { sub: 'Alocação de Perda na Unidade Geradora de Caixa (UGC)', ref: 'CPC 01 (R1), item 104', t: 'Na alocação de uma perda por desvalorização a uma Unidade Geradora de Caixa (UGC), reduz-se primeiramente o valor contábil de qualquer goodwill alocado à UGC e, depois, aos demais ativos proporcionalmente ao valor contábil de cada um.', f: 'A perda por impairment de uma UGC deve ser alocada primeiramente ao saldo de Caixa e Equivalentes de Caixa.', exp: 'Ordem na UGC: 1º abate o Goodwill da UGC; 2º rateia o restante proporcionalmente aos demais ativos da UGC.' }
  ],
  13: [
    { sub: 'Três Requisitos para Reconhecimento de Provisão', ref: 'CPC 25, item 14', t: 'Uma provisão deve ser reconhecida no Passivo quando: (a) a entidade tem uma obrigação presente (legal ou não formalizada) como resultado de evento passado; (b) seja provável uma saída de recursos; e (c) possa ser feita uma estimativa confiável.', f: 'Qualquer risco remoto de processo trabalhista futuro deve ser imediatamente provisionado no Passivo Circulante pelo valor total pedido pelo autor.', exp: 'Provisão = Passivo de prazo ou valor incerto, exigindo obrigação presente + saída provável + estimativa confiável.' },
    { sub: 'Tratamento do Passivo Contingente', ref: 'CPC 25', t: 'Um passivo contingente (cuja saída de recursos é apenas possível, ou remota) não deve ser reconhecido no Balanço Patrimonial; se a saída for possível, é divulgado em notas explicativas; se for remota, nem sequer exige divulgação.', f: 'Os passivos contingentes de perda possível são contabilizados em metade do valor no Passivo Não Circulante.', exp: 'Saída Provável = Provisão (no Balanço); Saída Possível = Nota Explicativa; Saída Remota = nada faz.' },
    { sub: 'Tratamento do Ativo Contingente', ref: 'CPC 25', t: 'Os ativos contingentes não são reconhecidos nas demonstrações contábeis; quando a entrada de benefícios econômicos for provável, o ativo contingente é divulgado em notas explicativas, e só é reconhecido no Balanço quando for praticamente certo.', f: 'Um processo judicial movido pela empresa cuja chance de ganho é estimada pelos advogados como provável (60%) já deve ser contabilizado como Ativo Circulante.', exp: 'Ativo Contingente: Praticamente certo -> reconhece Ativo (deixa de ser contingente); Provável -> Nota Explicativa; Possível/Remoto -> nada.' },
    { sub: 'Contrato Oneroso e Provisão', ref: 'CPC 25, item 66', t: 'Se a entidade tiver um contrato oneroso (aquele em que os custos inevitáveis para satisfazer as obrigações excedem os benefícios econômicos a receber), a obrigação presente sob o contrato deve ser reconhecida e mensurada como provisão.', f: 'Prejuízos operacionais futuros esperados para o próximo exercício devem ser provisionados antecipadamente no passivo do balanço atual.', exp: 'Prejuízos operacionais futuros não são provisionados (item 63), mas contratos onerosos exigem provisão pelo menor custo de saída.' },
    { sub: 'Reembolso Esperado de Terceiros em Provisões', ref: 'CPC 25, item 53', t: 'Quando se espera que parte ou o total do gasto exigido para liquidar uma provisão seja reembolsado por outra parte (ex: seguradora), o reembolso só é reconhecido no Ativo quando for praticamente certo que será recebido.', f: 'O valor esperado de reembolso de seguro deve ser abatido diretamente do saldo da provisão no Passivo, mesmo quando o recebimento for apenas possível.', exp: 'No Balanço, a provisão e o ativo de reembolso (quando praticamente certo) não se compensam; na DRE, a despesa pode ser apresentada líquida.' }
  ],
  14: [
    { sub: 'Composição do Patrimônio Líquido na Lei 6.404/76', ref: 'Lei 6.404/76, Art. 178, §2º, III', t: 'Após as Leis 11.638/07 e 11.941/09, o Patrimônio Líquido divide-se em: Capital Social, Reservas de Capital, Ajustes de Avaliação Patrimonial, Reservas de Lucros, Ações em Tesouraria e Prejuízos Acumulados.', f: 'A conta Lucros Acumulados e a Reserva de Reavaliação continuam sendo contas obrigatórias com saldo positivo permanente no balanço das S.A.', exp: 'Nas S/A, o lucro líquido deve ser totalmente destinado, não restando saldo positivo na conta Lucros Acumulados ao fim do exercício.' },
    { sub: 'Capital Subscrito, a Integralizar e Realizado', ref: 'Lei 6.404/76', t: 'O Capital Social a Integralizar (ou a Realizar) é conta retificadora de natureza devedora que deduz o Capital Subscrito para evidenciar o Capital Social Realizado (efetivamente integralizado pelos sócios).', f: 'O Capital a Integralizar é classificado no Ativo Circulante como créditos contra acionistas de curto prazo.', exp: 'Capital Realizado = Capital Subscrito - Capital a Integralizar (retificadora do PL).' },
    { sub: 'Reservas de Capital (Origem não transitada pelo Resultado)', ref: 'Lei 6.404/76, Art. 182, §1º', t: 'Classificam-se como Reservas de Capital o ágio na emissão de ações, o produto da alienação de partes beneficiárias e bônus de subscrição.', f: 'As subvenções governamentais para investimento e os prêmios na emissão de debêntures continuam sendo contabilizados diretamente como Reserva de Capital.', exp: 'Desde a Lei 11.638/07, subvenções para investimento e prêmio de debêntures transitam pelo resultado (e depois podem ir a Reserva de Incentivos Fiscais).' },
    { sub: 'Reserva Legal: Percentual e Limites (Obrigatório e Facultativo)', ref: 'Lei 6.404/76, Art. 193', t: 'Da parcela do lucro líquido do exercício, 5% serão aplicados, antes de qualquer outra destinação, na constituição da Reserva Legal, que não excederá de 20% do capital social (limite obrigatório).', f: 'A Reserva Legal é constituída à razão de 10% sobre a receita bruta anual e tem como limite único 50% do ativo imobilizado.', exp: 'Reserva Legal: 5% do Lucro Líquido; limite obrigatório = 20% do Capital Social; limite facultativo = RL + Reservas de Capital = 30% do Capital Social.' },
    { sub: 'Reservas de Lucros: Contingências, Lucros a Realizar e Retenção', ref: 'Lei 6.404/76, Arts. 194 a 197', t: 'Integram as Reservas de Lucros: a Reserva Legal, a Reserva Estatutária, a Reserva para Contingências, a Reserva de Incentivos Fiscais, a Reserva de Retenção de Lucros (orçamento de capital) e a Reserva de Lucros a Realizar.', f: 'A Reserva para Contingências registrada no Patrimônio Líquido substitui a provisão trabalhista do Passivo Exigível para fatos geradores já ocorridos.', exp: 'Reserva para Contingências (no PL) visa compensar em exercício futuro a diminuição do lucro decorrente de perda julgada provável (ex: geada futura).' }
  ],
  15: [
    { sub: 'Ações em Tesouraria', ref: 'Lei 6.404/76, Art. 182, §5º', t: 'As ações em tesouraria, adquiridas pela própria companhia, têm natureza devedora e devem ser destacadas no balanço como dedução da conta do Patrimônio Líquido que registrar a origem dos recursos aplicados na sua aquisição.', f: 'A compra de ações da própria companhia para manutenção em tesouraria é classificada como Investimento Temporário no Ativo Circulante.', exp: 'Ações em Tesouraria = conta retificadora do Patrimônio Líquido (natureza devedora).' },
    { sub: 'Resultado na Alienação de Ações em Tesouraria', ref: 'CPC 39 / Lei 6.404/76', t: 'O ganho ou a perda apurados na venda (recolocação) ou cancelamento de ações em tesouraria não transitam pela DRE, sendo registrados diretamente em contas do Patrimônio Líquido (Reservas de Capital ou Reservas de Lucros).', f: 'O lucro obtido pela companhia na revenda de suas próprias ações em tesouraria constitui Receita Operacional Tributável na DRE.', exp: 'Transações com sócios na qualidade de titulares (como ações em tesouraria e custos de emissão de ações) afetam diretamente o PL, nunca a DRE.' },
    { sub: 'Gastos na Emissão de Ações', ref: 'CPC 08', t: 'Os custos de transação incorridos e diretamente atribuíveis à emissão de novas ações (como comissões de coordenação e taxas de registro) são contabilizados como redutores do Patrimônio Líquido, líquidos dos efeitos tributários.', f: 'Os custos de emissão de novas ações são sempre lançados como Despesa Administrativa na DRE do mês da oferta pública.', exp: 'Pelo CPC 08, custos de captação de recursos próprios deduzem o PL (emissão realizada); só vão para a DRE se a operação de emissão fracassar/for cancelada.' },
    { sub: 'Dividendo Obrigatório e Omissão do Estatuto', ref: 'Lei 6.404/76, Art. 202', t: 'Quando o estatuto social for omisso quanto ao dividendo obrigatório, os acionistas têm direito a receber no mínimo metade (50%) do lucro líquido do exercício ajustado (após dedução da Reserva Legal e da Reserva para Contingências).', f: 'Sendo omisso o estatuto da S.A., o dividendo mínimo obrigatório corresponderá sempre a 10% do faturamento bruto anual.', exp: 'Estatuto omisso = 50% do Lucro Líquido Ajustado. Se o estatuto era omisso e passar a prever, não pode fixar menos de 25% do LL ajustado.' },
    { sub: 'Juros sobre o Capital Próprio (JSCP)', ref: 'Lei 9.249/95 e Deliberação CVM', t: 'Para fins societários (CVM/CPC), os Juros sobre o Capital Próprio (JSCP) recebem tratamento contábil de destinação de lucro (debitando-se Lucros Acumulados no PL), podendo ser imputados ao valor dos dividendos obrigatórios pelo seu valor líquido do IRRF.', f: 'Nas demonstrações contábeis societárias das companhias abertas, os JSCP são obrigatoriamente mantidos como despesa financeira sem ajuste no PL.', exp: 'Fiscalmente os JSCP são dedutíveis, mas societariamente são tratados como distribuição de resultado (e entram no dividendo obrigatório pelo líquido).' }
  ],
  16: [
    { sub: 'Encerramento das Contas de Resultado na ARE', ref: 'Técnica Contábil', t: 'Na Apuração do Resultado do Exercício (ARE), as contas de despesas (natureza devedora) são encerradas mediante créditos e as contas de receitas (natureza credora) são encerradas mediante débitos, em contrapartida à conta transitória Resultado do Exercício.', f: 'Durante a ARE, as contas de receitas são debitadas contra a conta Caixa para zerar o saldo financeiro.', exp: 'Para zerar Receitas (credoras), debita-se Receita e credita-se ARE; para zerar Despesas (devedoras), credita-se Despesa e debita-se ARE.' },
    { sub: 'Absorção de Prejuízos Acumulados (Ordem Legal)', ref: 'Lei 6.404/76, Art. 189, par. único', t: 'O prejuízo do exercício será obrigatoriamente absorvido pelos lucros acumulados, pelas reservas de lucros e pela reserva legal, nessa exata ordem; as reservas de capital só podem ser usadas após esgotadas todas as reservas de lucros.', f: 'Havendo prejuízo no exercício, deve-se reduzir primeiramente o Capital Social antes de utilizar a Reserva Legal.', exp: 'Ordem obrigatória do Art. 189: 1º Lucros Acumulados; 2º Reservas de Lucros; 3º Reserva Legal (última das reservas de lucros); depois Reserva de Capital.' },
    { sub: 'Participações Estatutárias sobre o Lucro', ref: 'Lei 6.404/76, Art. 187, VI e Art. 190', t: 'As participações de debêntures, de empregados, de administradores e de partes beneficiárias serão determinadas, sucessivamente e nessa ordem, com base nos lucros que remanescerem depois de deduzida a participação anteriormente calculada e os prejuízos acumulados/IR.', f: 'As participações estatutárias dos administradores são calculadas diretamente sobre a Receita Bruta antes da dedução do imposto de renda.', exp: 'Ordem das participações (DEAPF): 1º Debêntures; 2º Empregados; 3º Administradores; 4º Partes Beneficiárias; 5º Fundos de Assistência.' },
    { sub: 'Despesas Antecipadas e Regime de Competência', ref: 'Regime de Competência', t: 'Os pagamentos antecipados de seguros ou aluguéis a vencer são ativados como Despesas Antecipadas (Ativo) e apropriados à DRE proporcionalmente ao tempo decorrido (pro rata temporis).', f: 'O prêmio de seguro anual pago à vista na assinatura da apólice deve ser reconhecido 100% como despesa operacional no dia do pagamento.', exp: 'Pelo regime de competência, seguro pago antecipadamente é Ativo (Despesa do Exercício Seguinte) e vira despesa mês a mês.' },
    { sub: 'Receitas Antecipadas (Adiantamento de Clientes)', ref: 'Regime de Competência', t: 'O recebimento antecipado de clientes por mercadorias ou serviços ainda não entregues gera um Passivo (Adiantamento de Clientes ou Receita Diferida), só transitando para a DRE quando ocorrer a efetiva entrega ou prestação.', f: 'Todo adiantamento recebido de clientes em dinheiro deve ser reconhecido imediatamente como Receita Bruta de Vendas no mês do recebimento.', exp: 'Recebimento antes do fato gerador (entrega do bem/serviço) é obrigação (Passivo) até que a performance seja cumprida.' }
  ],
  17: [
    { sub: 'Estrutura do Balanço Patrimonial (Art. 178 da LSA)', ref: 'Lei 6.404/76, Art. 178', t: 'No Balanço Patrimonial, o Ativo divide-se em Ativo Circulante e Ativo Não Circulante (composto por Realizável a Longo Prazo, Investimentos, Imobilizado e Intangível), e o Passivo divide-se em Passivo Circulante, Passivo Não Circulante e Patrimônio Líquido.', f: 'O grupo Ativo Diferido e o grupo Resultados de Exercícios Futuros continuam existindo como grupos autônomos obrigatórios na Lei 6.404/76.', exp: 'O Ativo Diferido (Lei 11.941/09) e os Resultados de Exercícios Futuros (Lei 11.638/07) foram extintos.' },
    { sub: 'Ordem de Liquidez e Exigibilidade', ref: 'Lei 6.404/76, Art. 178, §1º', t: 'No Balanço Patrimonial, as contas do Ativo são dispostas em ordem decrescente de grau de liquidez, enquanto as contas do Passivo são dispostas em ordem decrescente de grau de exigibilidade.', f: 'As contas do Ativo são ordenadas da menor para a maior liquidez, iniciando pelo Ativo Intangível no topo do balanço.', exp: 'Ativo = ordem decrescente de liquidez (começa por Caixa); Passivo = ordem decrescente de exigibilidade.' },
    { sub: 'Critério de Classificação: Exercício Social vs. Ciclo Operacional', ref: 'Lei 6.404/76, Art. 179, par. único', t: 'Classificam-se no Circulante as disponibilidades e os direitos/obrigações realizáveis no curso do exercício social subsequente (12 meses); porém, se o ciclo operacional da empresa tiver duração maior que o exercício social, a classificação terá por base o prazo desse ciclo.', f: 'Mesmo que o ciclo operacional de um estaleiro naval seja de 36 meses, o prazo do Ativo Circulante será sempre limitado a 12 meses.', exp: 'Se Ciclo Operacional <= 12 meses -> usa 12 meses; se Ciclo Operacional > 12 meses -> prevalece o Ciclo Operacional.' },
    { sub: 'Ativo Não Circulante Mantido para Venda', ref: 'CPC 31', t: 'Um ativo não circulante cujo valor contábil será recuperado principalmente por meio de transação de venda altamente provável (em até 12 meses) é reclassificado para o Ativo Circulante (Ativo Não Circulante Mantido para Venda) e cessa sua depreciação.', f: 'Os ativos mantidos para venda imediata continuam sendo depreciados normalmente dentro do subgrupo Imobilizado.', exp: 'Pelo CPC 31, o Ativo Não Circulante Mantido para Venda vai para o Ativo Circulante, é avaliado pelo menor entre VC e Valor Justo Líquido de Venda, e não deprecia.' },
    { sub: 'Propriedades para Investimento', ref: 'CPC 28', t: 'Propriedade para investimento é a propriedade (terreno ou edifício) mantida para auferir aluguel ou para valorização do capital (ou ambos), sendo classificada no subgrupo Investimentos do Ativo Não Circulante.', f: 'Os terrenos mantidos pela empresa para valorização de capital a longo prazo são classificados obrigatoriamente no Ativo Circulante.', exp: 'Propriedade para Investimento (CPC 28) fica no ANC - Investimentos, podendo ser mensurada ao custo ou ao valor justo (com variação na DRE).' }
  ],
  18: [
    { sub: 'Deduções da Receita Bruta na DRE', ref: 'Lei 6.404/76, Art. 187, I', t: 'Para se apurar a Receita Líquida de Vendas na DRE, deduzem-se da Receita Bruta: as devoluções e vendas canceladas, os descontos concedidos incondicionalmente (comerciais) e os impostos e contribuições incidentes sobre vendas (ICMS, ISS, PIS, COFINS).', f: 'Os descontos financeiros concedidos por pagamento antecipado e a despesa com PCLD são deduções diretas da Receita Bruta.', exp: 'Desconto condicional (financeiro) concedido é Despesa Financeira; PCLD é Despesa Operacional (Comercial/Vendas).' },
    { sub: 'IPI e ICMS-ST na Receita Bruta Societária', ref: 'CPC 47', t: 'Pelo CPC 47, valores coletados em nome de terceiros (como o IPI faturado e o ICMS por Substituição Tributária cobrado do comprador) não geram aumento do patrimônio líquido da entidade e são excluídos da Receita de Contratos com Clientes.', f: 'O ICMS-ST retido pela indústria na condição de substituta tributária constitui receita operacional própria da indústria.', exp: 'Tributos cobrados por fora em nome do Estado (IPI e ICMS-ST) não integram a receita líquida da entidade vendedora.' },
    { sub: 'Despesas Operacionais e Resultado Financeiro', ref: 'Lei 6.404/76, Art. 187, III', t: 'Na estrutura da DRE, após o Lucro Bruto, deduzem-se as despesas com vendas, as despesas gerais e administrativas, e computam-se as outras receitas/despesas operacionais e o resultado financeiro líquido (receitas financeiras menos despesas financeiras).', f: 'As despesas financeiras com juros bancários são deduzidas antes do Lucro Bruto, integrando o Custo das Mercadorias Vendidas.', exp: 'Lucro Bruto = Receita Líquida - CMV/CPV/CSP. Despesas comerciais, administrativas e financeiras vêm depois do Lucro Bruto.' },
    { sub: 'Outras Receitas e Despesas (Antigo Resultado Não Operacional)', ref: 'Lei 6.404/76 e Lei 11.941/09', t: 'Com a Lei nº 11.941/2009, foi extinta a segregação entre resultado operacional e resultado não operacional na DRE; ganhos ou perdas na alienação de bens do imobilizado compõem hoje as Outras Receitas e Despesas (dentro do resultado antes dos tributos).', f: 'O lucro na venda de um imóvel de uso continua sendo classificado no grupo autônomo denominado Resultado Não Operacional.', exp: 'A Lei 11.941/09 substituiu "Receitas e Despesas Não Operacionais" por "Outras Receitas e Outras Despesas".' },
    { sub: 'Lucro por Ação e Resultados Abrangentes (DRA)', ref: 'Lei 6.404/76 e CPC 26', t: 'A DRE encerra-se com o Lucro ou Prejuízo Líquido do Exercício e a divulgação do montante do lucro ou prejuízo líquido por ação do capital social; já os outros resultados abrangentes (ORA) são evidenciados na Demonstração do Resultado Abrangente (DRA).', f: 'Os ajustes de avaliação patrimonial decorrentes de instrumentos financeiros disponíveis para venda transitam obrigatoriamente pelo Lucro Bruto da DRE.', exp: 'Outros Resultados Abrangentes (ORA, como AAP) transitam pela DRA e pelo PL sem passar pela DRE no momento do ajuste.' }
  ],
  19: [
    { sub: 'Caixa e Equivalentes de Caixa na DFC', ref: 'CPC 03 (R2)', t: 'Equivalentes de caixa são aplicações financeiras de curto prazo (em regra com vencimento original de até 3 meses da contratação), de alta liquidez, prontamente conversíveis em montante conhecido de caixa e sujeitas a insignificante risco de mudança de valor.', f: 'Ações negociadas em bolsa de valores de alta liquidez são classificadas como equivalentes de caixa na DFC.', exp: 'Ações têm risco significativo de mudança de valor, logo não são equivalentes de caixa (salvo ações preferenciais resgatáveis com data próxima fixada).' },
    { sub: 'Classificação das Atividades: Operacionais, Investimento e Financiamento', ref: 'CPC 03 (R2)', t: 'Os fluxos operacionais decorrem das principais atividades geradoras de receita; os de investimento referem-se à aquisição e venda de ativos de longo prazo (imobilizado, intangível, participações); e os de financiamento alteram o tamanho e a composição do capital próprio e dos empréstimos.', f: 'O recebimento pela venda à vista de uma máquina do Ativo Imobilizado é classificado como fluxo de caixa das atividades operacionais.', exp: 'Compra e venda de imobilizado/intangível pelo valor recebido em caixa = Atividade de Investimento.' },
    { sub: 'Classificação de Juros e Dividendos (Pagos e Recebidos)', ref: 'CPC 03 (R2), itens 31-34', t: 'O CPC 03 encoraja fortemente as entidades não financeiras a classificarem juros pagos, juros recebidos e dividendos recebidos como atividades operacionais, e dividendos/JSCP pagos como financiamento (admitindo-se a classificação alternativa de juros pagos em financiamento e recebidos em investimento).', f: 'O pagamento de dividendos aos acionistas da empresa deve ser classificado exclusivamente nas atividades de investimento.', exp: 'Dividendos pagos: Financiamento (regra/encorajado) ou Operacional; NUNCA Investimento.' },
    { sub: 'Ajustes do Lucro Líquido no Método Indireto', ref: 'CPC 03 (R2)', t: 'No método indireto da DFC, o lucro líquido é ajustado pelos itens que não afetam o caixa (soma-se a depreciação e a PCLD, exclui-se o ganho de equivalência patrimonial e o lucro na venda de imobilizado) e pelas variações nas contas operacionais de giro.', f: 'No método indireto, o aumento do saldo da conta Clientes e o aumento da conta Estoques são somados ao lucro líquido.', exp: 'No método indireto: aumento de ativo operacional (Clientes, Estoques) = SUBTRAI; aumento de passivo operacional (Fornecedores) = SOMA.' },
    { sub: 'Transações que Não Envolvem Caixa', ref: 'CPC 03 (R2), item 43', t: 'Transações de investimento e financiamento que não envolvem o uso de caixa ou equivalentes de caixa (como aquisição de imobilizado mediante assunção direta de financiamento ou conversão de dívida em capital) devem ser excluídas da DFC e divulgadas nas notas explicativas.', f: 'A integralização de capital social mediante entrega de um terreno deve figurar na DFC como entrada de financiamento e saída de investimento.', exp: 'Transações puramente não-caixa não entram na DFC (CPC 03, item 43).' }
  ],
  20: [
    { sub: 'Obrigatoriedade da DLPA e Substituição pela DMPL', ref: 'Lei 6.404/76, Art. 186, §2º e CPC 26', t: 'Pela Lei 6.404/76, a Demonstração de Lucros ou Prejuízos Acumulados (DLPA) pode ser incluída na Demonstração das Mutações do Patrimônio Líquido (DMPL) se elaborada e publicada pela companhia; pelo CPC 26 e para companhias abertas (CVM), a DMPL é obrigatória.', f: 'A publicação simultânea de duas peças separadas para DLPA e DMPL é exigida sob pena de nulidade do balanço.', exp: 'Como a DMPL abrange todas as contas do PL (inclusive Lucros/Prejuízos Acumulados), quem publica a DMPL fica dispensado de publicar a DLPA em separado.' },
    { sub: 'Mutações Permutativas vs. Modificativas na DMPL', ref: 'Técnica Contábil', t: 'Na DMPL, a constituição de reservas de lucros e o aumento de capital com reservas são mutações meramente permutativas dentro do PL (não alteram o total do PL), enquanto o lucro líquido do exercício, o aumento de capital em dinheiro e a distribuição de dividendos alteram o total do PL.', f: 'A transferência de Lucros Acumulados para a Reserva Legal aumenta o saldo total do Patrimônio Líquido na DMPL.', exp: 'D - Lucros Acumulados / C - Reserva Legal é permuta interna entre contas do PL, mantendo o PL total inalterado.' },
    { sub: 'Evidenciação de Ajustes de Exercícios Anteriores (Erros e Políticas)', ref: 'Lei 6.404/76, Art. 186, §1º e CPC 23', t: 'Como ajustes de exercícios anteriores na conta de Lucros ou Prejuízos Acumulados (DMPL/DLPA), serão considerados apenas os decorrentes de efeitos da mudança de critério (política) contábil ou da retificação de erro imputável a determinado exercício anterior.', f: 'A mudança na estimativa da alíquota de PCLD para o ano corrente é lançada retrospectivamente como ajuste de exercícios anteriores na DMPL.', exp: 'Mudança de estimativa tem efeito prospectivo (DRE atual/futura); apenas mudança de política contábil e retificação de erro de período anterior ajustam o saldo inicial de Lucros Acumulados.' },
    { sub: 'Dividendos Propostos e Adicionais na DMPL', ref: 'ICPC 08 / CPC 26', t: 'A parcela dos dividendos correspondente ao dividendo mínimo obrigatório é transferida de Lucros Acumulados para o Passivo Circulante (Dividendos a Pagar), enquanto a parcela proposta acima do obrigatório (antes da aprovação pela AGO) permanece destacada no PL.', f: 'Qualquer intenção verbal da diretoria de pagar dividendos extras já reduz imediatamente o Patrimônio Líquido antes do fim do exercício.', exp: 'Pela ICPC 08, apenas o dividendo obrigatório (obrigação presente) vira Passivo no encerramento; o dividendo adicional proposto aguarda aprovação da AGO.' },
    { sub: 'Resultado Abrangente Total na DMPL', ref: 'CPC 26 (R1)', t: 'A DMPL deve apresentar o resultado abrangente total do período, segregando o lucro líquido do período e cada item dos outros resultados abrangentes (ORA), bem como as transações com os proprietários na sua qualidade de proprietários.', f: 'Os outros resultados abrangentes são proibidos de transitar pela DMPL.', exp: 'O CPC 26 exige na DMPL a reconciliação de cada componente do PL, destacando o resultado líquido e os outros resultados abrangentes.' }
  ],
  21: [
    { sub: 'Obrigatoriedade e Finalidade da DVA', ref: 'Lei 6.404/76, Art. 176, V e CPC 09', t: 'A Demonstração do Valor Adicionado (DVA) é obrigatória pela Lei 6.404/76 exclusivamente para as companhias abertas e evidencia o valor da riqueza econômica gerada pela companhia e a sua distribuição entre os elementos que contribuíram para a geração dessa riqueza.', f: 'A DVA é obrigatória para todas as sociedades limitadas de pequeno porte e substitui a Demonstração dos Fluxos de Caixa.', exp: 'Na Lei 6.404/76, a DVA é obrigatória apenas para S.A. de capital aberto.' },
    { sub: 'Insumos Adquiridos de Terceiros (Consumo pelo Bruto)', ref: 'CPC 09', t: 'Na primeira parte da DVA (Geração da Riqueza), tanto as receitas quanto os insumos adquiridos de terceiros (matérias-primas, mercadorias, energia, serviços de terceiros) são computados pelos seus valores brutos, incluindo todos os tributos incidentes (ICMS, IPI, PIS, COFINS).', f: 'Na DVA, o custo das mercadorias vendidas e as receitas são apresentados líquidos de todos os impostos indiretos.', exp: 'Diferentemente da DRE, na DVA a receita e os insumos incluem os tributos (para que a parcela total de Impostos, Taxas e Contribuições apareça na distribuição ao Governo).' },
    { sub: 'Depreciação, Amortização e Exaustão na DVA', ref: 'CPC 09', t: 'Na estrutura da DVA, a depreciação, a amortização e a exaustão são deduzidas do Valor Adicionado Bruto para se apurar o Valor Adicionado Líquido Produzido pela Entidade.', f: 'A despesa de depreciação é classificada na segunda parte da DVA como Remuneração de Capitais de Terceiros.', exp: 'Valor Adicionado Bruto (-) Depreciação, Amortização e Exaustão = Valor Adicionado Líquido Produzido pela Entidade.' },
    { sub: 'Valor Adicionado Recebido em Transferência', ref: 'CPC 09', t: 'O resultado de equivalência patrimonial, as receitas financeiras e os dividendos relativos a investimentos avaliados ao custo compõem o grupo Valor Adicionado Recebido em Transferência, que se soma ao Valor Adicionado Líquido Produzido para formar o Valor Adicionado Total a Distribuir.', f: 'As receitas financeiras de aplicações bancárias são classificadas como Insumos Adquiridos de Terceiros na DVA.', exp: 'Riqueza gerada por outras entidades e transferida para a empresa (MEP, receitas financeiras, dividendos) = Valor Adicionado Recebido em Transferência.' },
    { sub: 'Quatro Grupos de Distribuição da Riqueza na DVA', ref: 'CPC 09', t: 'Na segunda parte da DVA, o Valor Adicionado Total a Distribuir é repartido em 4 grupos: (1) Pessoal (salários, benefícios, FGTS); (2) Impostos, Taxas e Contribuições (inclusive INSS patronal); (3) Remuneração de Capitais de Terceiros (juros e aluguéis); e (4) Remuneração de Capitais Próprios (dividendos, JSCP e lucros retidos).', f: 'O INSS patronal sobre a folha de salários e os aluguéis pagos a terceiros são classificados no grupo Pessoal da DVA.', exp: 'Atenção FGV: FGTS vai em Pessoal; INSS patronal vai em Impostos, Taxas e Contribuições; Aluguéis e Juros vão em Remuneração de Capitais de Terceiros.' }
  ],
  22: [
    { sub: 'Alcance do Método da Equivalência Patrimonial (MEP)', ref: 'Lei 6.404/76, Art. 248 e CPC 18', t: 'São avaliados pelo Método da Equivalência Patrimonial (MEP) os investimentos permanentes em sociedades coligadas, em sociedades controladas e em outras sociedades que façam parte de um mesmo grupo ou estejam sob controle comum (inclusive joint ventures).', f: 'Qualquer aplicação temporária de 1% em ações negociadas em bolsa com finalidade especulativa deve ser avaliada pelo MEP.', exp: 'Art. 248 da LSA + CPC 18: MEP aplica-se a coligadas, controladas, controladas em conjunto (joint ventures) e sociedades sob controle comum.' },
    { sub: 'Conceito de Coligada e Presunção de Influência Significativa', ref: 'Lei 6.404/76, Art. 243, §§ 1º, 4º e 5º', t: 'São coligadas as sociedades nas quais a investidora tenha influência significativa, presumindo-se esta quando a investidora detém 20% ou mais do capital votante da investida, sem controlá-la.', f: 'A influência significativa exige a titularidade mínima de 50% mais uma ação do capital total da investida.', exp: 'Presunção relativa de influência significativa: >= 20% do capital votante (ou poder de participar nas decisões financeiras/operacionais sem controlar).' },
    { sub: 'Contabilização do Lucro e dos Dividendos no MEP', ref: 'CPC 18 (R2)', t: 'Pelo MEP, quando a investida apura lucro líquido, a investidora aumenta o valor do investimento a crédito de Receita de Equivalência Patrimonial (DRE); quando a investida distribui dividendos, a investidora debita Caixa/Dividendos a Receber e credita a própria conta de Investimentos (fato permutativo).', f: 'No MEP, os dividendos distribuídos pela investida são contabilizados pela investidora como uma segunda receita operacional na DRE.', exp: 'No MEP: Lucro da investida -> aumenta Investimento e gera Receita de MEP; Dividendo da investida -> reduz Investimento contra Caixa/Dividendos a Receber.' },
    { sub: 'Lucros Não Realizados em Transações Entre Partes (Upstream e Downstream)', ref: 'CPC 18 (R2), item 28', t: 'No cálculo da equivalência patrimonial, os lucros não realizados decorrentes de vendas de ativos entre a investidora e suas coligadas ou controladas (enquanto os bens permanecerem em estoque e não forem vendidos a terceiros independentes) devem ser eliminados.', f: 'Os lucros de vendas de mercadorias para uma controlada que permanecem integralmente no estoque da compradora são reconhecidos 100% no MEP.', exp: 'Enquanto a mercadoria não for vendida para terceiros fora do grupo, o lucro interno não realizado é eliminado.' },
    { sub: 'Variações Diretas no PL da Investida (Reflexo em ORA)', ref: 'CPC 18 (R2), item 10', t: 'Quando a investida reconhece variações diretamente em seu Patrimônio Líquido por meio de Outros Resultados Abrangentes (ex: ajuste de avaliação patrimonial), a investidora registra sua participação proporcional diretamente em seu próprio PL (em ORA), sem transitar pela DRE.', f: 'Qualquer ajuste patrimonial da investida deve ser lançado pela investidora como despesa financeira na DRE.', exp: 'Se na investida afetou DRE -> na investidora afeta DRE; se na investida afetou ORA/PL -> na investidora afeta ORA/PL.' }
  ],
  23: [
    { sub: 'Método de Aquisição em Combinação de Negócios', ref: 'CPC 15 (R1)', t: 'Todas as combinações de negócios são contabilizadas pelo método de aquisição, identificando-se o adquirente, determinando-se a data de aquisição e mensurando-se os ativos identificáveis adquiridos e os passivos assumidos pelos seus respectivos valores justos na data da aquisição.', f: 'Na combinação de negócios, os ativos e passivos da adquirida são mantidos sempre pelo custo histórico contábil sem avaliação a valor justo.', exp: 'Pelo CPC 15: 1º identifica adquirente; 2º data de aquisição; 3º mensura ativos/passivos da adquirida a VALOR JUSTO; 4º apura Goodwill ou Compra Vantajosa.' },
    { sub: 'Apuração de Goodwill vs. Compra Vantajosa (Deságio)', ref: 'CPC 15 (R1), itens 32-34', t: 'Se a contraprestação transferida superar o valor justo líquido dos ativos e passivos identificáveis adquiridos, reconhece-se um ágio por expectativa de rentabilidade futura (Goodwill); se for inferior, reconhece-se um ganho por compra vantajosa diretamente no resultado (DRE) na data da aquisição.', f: 'O ganho por compra vantajosa (deságio) deve ser mantido no Passivo Não Circulante e amortizado em vinte anos.', exp: 'Goodwill -> Ativo (não amortiza no balanço consolidado, sujeito a impairment); Compra Vantajosa -> Receita/Ganho imediato na DRE da adquirente.' },
    { sub: 'Mais-Valia de Ativos Líquidos na Demonstração Individual', ref: 'ICPC 09 / CPC 15', t: 'Na contabilidade individual da controladora no Brasil, o valor do investimento adquirido em controlada é desdobrado em: equivalência patrimonial (valor contábil), mais-valia dos ativos líquidos (diferença entre valor justo e valor contábil) e goodwill.', f: 'A mais-valia de máquinas e estoques da controlada nunca é amortizada ou baixada na medida em que os bens são realizados.', exp: 'A mais-valia é amortizada/baixada na mesma proporção em que o ativo que lhe deu origem é depreciado ou baixado na investida.' },
    { sub: 'Gastos Relacionados à Aquisição', ref: 'CPC 15 (R1), item 53', t: 'Os custos diretamente relacionados à combinação de negócios (como honorários de consultores, advogados, avaliadores e contadores para intermediar a operação) são reconhecidos como despesas no período em que são incorridos, não integrando o cálculo do goodwill.', f: 'Todos os honorários de advogados e consultores pagos para negociar a aquisição de uma empresa são somados ao valor do Goodwill.', exp: 'Pegadinha clássica FGV: no CPC 15, custos da transação de combinação de negócios são DESPESAS na DRE (não entram no custo da aquisição).' },
    { sub: 'Passivo Contingente Assumido em Combinação de Negócios', ref: 'CPC 15 (R1), item 23', t: 'Excepcionalmente ao CPC 25, em uma combinação de negócios o adquirente deve reconhecer na data da aquisição um passivo contingente assumido se for uma obrigação presente decorrente de eventos passados e seu valor justo puder ser mensurado com confiabilidade, mesmo que não seja provável a saída de recursos.', f: 'Passivos contingentes da adquirida jamais podem ser considerados na mensuração a valor justo de uma combinação de negócios.', exp: 'Exceção do CPC 15: passivo contingente assumido na combinação é reconhecido a valor justo na aquisição mesmo que a saída não seja provável.' }
  ],
  24: [
    { sub: 'Conceito de Controle e Obrigatoriedade de Consolidação', ref: 'CPC 36 (R3) e Lei 6.404/76', t: 'Um investidor controla uma investida quando está exposto a (ou tem direitos sobre) retornos variáveis decorrentes de seu envolvimento com a investida e tem a capacidade de afetar esses retornos por meio de seu poder sobre a investida, devendo elaborar demonstrações consolidadas.', f: 'As sociedades coligadas nas quais a investidora detém apenas 20% das ações devem ter seus ativos somados linha a linha no balanço consolidado.', exp: 'Consolidação integral aplica-se exclusivamente às CONTROLADAS; coligadas e joint ventures são avaliadas por MEP, sem consolidação linha a linha.' },
    { sub: 'Procedimentos de Eliminação na Consolidação', ref: 'CPC 36 (R3) e Lei 6.404/76, Art. 250', t: 'Nas demonstrações consolidadas, somam-se os ativos, passivos, receitas e despesas da controladora e das controladas, eliminando-se integralmente: a participação da controladora no PL da controlada, os saldos de contas a receber/pagar entre elas e as receitas/despesas e lucros não realizados intragrupo.', f: 'No balanço consolidado, os empréstimos concedidos pela controladora à sua controlada permanecem duplicados no Ativo e no Passivo Consolidado.', exp: 'Todas as transações, saldos recíprocos e lucros não realizados entre as sociedades do grupo econômico são 100% eliminados na consolidação.' },
    { sub: 'Participação dos Não Controladores (Minoritários)', ref: 'CPC 36 (R3)', t: 'A participação dos acionistas não controladores deve ser apresentada no Balanço Patrimonial Consolidado dentro do Patrimônio Líquido, separadamente do patrimônio líquido dos proprietários da controladora.', f: 'A participação dos acionistas minoritários é classificada no Passivo Circulante do Balanço Consolidado.', exp: 'Participação dos Não Controladores (PNC) integra o Patrimônio Líquido Consolidado, em linha destacada.' },
    { sub: 'Eliminação Integral vs. Proporcional em Transações Intragrupo', ref: 'CPC 36 (R3), item B86', t: 'Na consolidação, os ativos, passivos, receitas, despesas e fluxos de caixa intragrupo (bem como os lucros não realizados) são eliminados em sua totalidade (100%), e não apenas pelo percentual de participação da controladora.', f: 'Se a controladora detém 70% da controlada, apenas 70% das contas a receber e a pagar entre elas são eliminadas no balanço consolidado.', exp: 'Na consolidação, a eliminação dos saldos e lucros não realizados intragrupo é de 100% (nas vendas upstream, o efeito do lucro eliminado é dividido entre controladora e não controladores).' },
    { sub: 'Mudança na Participação Societária sem Perda de Controle', ref: 'CPC 36 (R3), item 23', t: 'As alterações na participação societária da controladora em uma controlada que não resultem na perda de controle da controlada são transações de capital (entre sócios) e devem ser contabilizadas diretamente no Patrimônio Líquido, sem gerar ganho ou perda na DRE.', f: 'Quando uma controladora que detinha 80% vende 10% das ações da controlada (mantendo 70% e o controle), o ganho é reconhecido na DRE consolidada.', exp: 'Enquanto não houver perda de controle, compra ou venda de fatia adicional em controlada é transação entre sócios (direto no PL).' }
  ],
  25: [
    { sub: 'Fórmulas dos Índices de Liquidez (Geral, Corrente, Seca e Imediata)', ref: 'Análise de Balanços', t: 'O Índice de Liquidez Corrente (AC / PC) mede a capacidade de pagamento no curto prazo; a Liquidez Seca exclui os estoques e despesas antecipadas do numerador; a Liquidez Imediata considera apenas as Disponibilidades / PC; e a Liquidez Geral soma (AC + RLP) / (PC + PNC).', f: 'O Índice de Liquidez Geral inclui o Ativo Imobilizado e o Ativo Intangível no numerador para medir a solvência operacional.', exp: 'LG = (AC + RLP) / (PC + PNC); LC = AC / PC; LS = (AC - Estoques - Desp. Antecipadas) / PC; LI = Disponível / PC.' },
    { sub: 'Capital Circulante Líquido (CCL)', ref: 'Análise de Balanços', t: 'O Capital Circulante Líquido (CCL ou Capital de Giro Líquido) é apurado pela diferença entre o Ativo Circulante e o Passivo Circulante (CCL = AC - PC); quando AC > PC, o CCL é positivo e a Liquidez Corrente é maior que 1.', f: 'Uma empresa com Índice de Liquidez Corrente igual a 0,80 apresenta Capital Circulante Líquido positivo.', exp: 'Se LC > 1 -> CCL > 0; se LC = 1 -> CCL = 0; se LC < 1 -> CCL < 0 (passivo circulante supera ativo circulante).' },
    { sub: 'Efeito de Transações sobre a Liquidez Corrente', ref: 'Análise de Balanços', t: 'Quando o Índice de Liquidez Corrente inicial é maior que 1 (ex: LC = 2,0), o pagamento de uma dívida de curto prazo (Fornecedores) com dinheiro do Caixa reduz igualmente o numerador e o denominador, provocando o AUMENTO do Índice de Liquidez Corrente.', f: 'Se a Liquidez Corrente é igual a 2,0, quitar um fornecedor à vista reduz o Índice de Liquidez Corrente.', exp: 'Matemática de frações: se AC/PC > 1 (ex: 200/100 = 2,0), subtrair o mesmo valor k (ex: 50) de ambos eleva a razão (150/50 = 3,0), mantendo o CCL inalterado!' },
    { sub: 'Análise Vertical e Análise Horizontal', ref: 'Análise de Balanços', t: 'A Análise Vertical (AV) evidencia a participação percentual de cada conta em relação a um total-base do mesmo período (Ativo Total no Balanço ou Receita Líquida na DRE), enquanto a Análise Horizontal (AH) mede a evolução temporal das contas ao longo de exercícios sucessivos.', f: 'A Análise Horizontal compara cada conta do Ativo Circulante exclusivamente com o Patrimônio Líquido do mesmo ano.', exp: 'Vertical = estrutura em um mesmo momento (coluna); Horizontal = evolução no tempo (linha).' },
    { sub: 'Índice de Solvência Geral', ref: 'Análise de Balanços', t: 'O Índice de Solvência Geral (Ativo Total / Passivo Exigível Total) verifica se todos os bens e direitos da entidade são suficientes para cobrir a totalidade das dívidas com terceiros; se for maior que 1, o Patrimônio Líquido é positivo.', f: 'Uma entidade com Passivo a Descoberto apresenta Índice de Solvência Geral superior a 1,5.', exp: 'Solvência Geral = Ativo Total / (PC + PNC). Se > 1, Ativo > Passivo Exigível (PL positivo).' }
  ],
  26: [
    { sub: 'Composição do Endividamento vs. Participação de Capitais de Terceiros', ref: 'Análise de Balanços', t: 'A Participação de Capitais de Terceiros (PCT = Passivo Exigível / PL ou Passivo Exigível / Passivo Total) mede o grau de dependência de recursos externos, enquanto a Composição do Endividamento (CE = PC / Passivo Exigível Total) revela a fração da dívida que vence no curto prazo.', f: 'Quanto maior for o índice de Composição do Endividamento (PC / PE), mais alongado é o perfil da dívida da empresa.', exp: 'Alta Composição do Endividamento (PC / PE próximo de 100%) é desfavorável, pois significa que quase toda a dívida vence no curto prazo.' },
    { sub: 'Imobilização do Patrimônio Líquido e dos Recursos Não Correntes', ref: 'Análise de Balanços', t: 'O índice de Imobilização do Patrimônio Líquido ((Investimentos + Imobilizado + Intangível) / PL) indica quanto do capital próprio foi aplicado no Ativo Permanente; se superar 100% sem Passivo Não Circulante suficiente, o CCL será negativo.', f: 'Quanto maior a Imobilização do Patrimônio Líquido, maior será a folga financeira no Ativo Circulante.', exp: 'Se todo o PL está imobilizado em ativos fixos, sobra menos capital próprio (Capital Próprio Circulante) para financiar o giro.' },
    { sub: 'Retorno sobre o Ativo (ROA/ROI) e Retorno sobre o Patrimônio Líquido (ROE)', ref: 'Análise de Balanços', t: 'O Retorno sobre o Ativo (ROA = Lucro / Ativo) mede a rentabilidade global dos recursos investidos na operação, enquanto o Retorno sobre o Patrimônio Líquido (ROE = Lucro Líquido / PL) mede a taxa de retorno auferida especificamente pelos proprietários/acionistas.', f: 'O ROE é calculado dividindo-se o faturamento bruto mensal pelo Passivo Circulante.', exp: 'ROA = rentabilidade do ativo total; ROE = rentabilidade do capital próprio (Patrimônio Líquido).' },
    { sub: 'Identidade DuPont (Decomposição do ROE)', ref: 'Análise de Balanços', t: 'Pela fórmula DuPont, o ROE pode ser decomposto no produto de três fatores: Margem Líquida (Lucro Líquido / Vendas) × Giro do Ativo (Vendas / Ativo Total) × Multiplicador de Alavancagem Financeira (Ativo Total / Patrimônio Líquido).', f: 'Pela análise DuPont, um aumento no Giro do Ativo mantendo constantes a margem e a alavancagem reduz o ROE.', exp: 'DuPont: ROE = (LL / Vendas) × (Vendas / Ativo) × (Ativo / PL) = Margem × Giro × Alavancagem.' },
    { sub: 'Grau de Alavancagem Financeira (GAF)', ref: 'Análise de Balanços', t: 'Quando o retorno gerado pelos ativos (ROA) é superior ao custo médio da dívida com terceiros (Ki), a alavancagem financeira é favorável (GAF > 1), fazendo com que o retorno dos acionistas (ROE) supere o ROA.', f: 'Se o custo dos empréstimos bancários for superior à rentabilidade operacional do ativo, o endividamento aumentará o ROE dos sócios.', exp: 'Se ROA > Custo da Dívida -> Alavancagem positiva (ROE > ROA). Se ROA < Custo da Dívida -> Alavancagem negativa (destrói valor do acionista).' }
  ],
  27: [
    { sub: 'Prazos Médios de Estocagem (PME), Recebimento (PMR) e Pagamento (PMP)', ref: 'Análise de Capital de Giro', t: 'O Prazo Médio de Renovação de Estoques (PME) indica quantos dias a mercadoria fica estocada antes da venda; o Prazo Médio de Recebimento de Vendas (PMR) indica quantos dias leva para receber dos clientes; e o Prazo Médio de Pagamento de Compras (PMP) indica em quantos dias os fornecedores são pagos.', f: 'O Prazo Médio de Recebimento é calculado dividindo-se o saldo do Ativo Imobilizado pelo Custo das Mercadorias Vendidas.', exp: 'PME = (Estoque Médio / CMV) × 360; PMR = (Clientes Médio / Vendas) × 360; PMP = (Fornecedores Médio / Compras) × 360.' },
    { sub: 'Ciclo Operacional (CO)', ref: 'Análise de Capital de Giro', t: 'O Ciclo Operacional compreende todo o período desde a aquisição da matéria-prima ou mercadoria até o efetivo recebimento em caixa pela venda do produto, sendo calculado pela soma: Ciclo Operacional = PME + PMR.', f: 'O Ciclo Operacional corresponde à diferença entre o Prazo Médio de Pagamento a Fornecedores e o Prazo Médio de Estocagem.', exp: 'Ciclo Operacional (CO) = PME + PMR.' },
    { sub: 'Ciclo Financeiro ou Ciclo de Caixa (CF)', ref: 'Análise de Capital de Giro', t: 'O Ciclo Financeiro (ou Ciclo de Conversão de Caixa) mede o intervalo de tempo entre o desembolso para pagamento aos fornecedores e o recebimento das vendas dos clientes: Ciclo Financeiro = Ciclo Operacional - PMP (ou seja, CF = PME + PMR - PMP).', f: 'O Ciclo Financeiro é obtido somando-se o Prazo Médio de Pagamento aos Fornecedores ao Ciclo Operacional.', exp: 'CF = PME + PMR - PMP. Quanto menor o Ciclo Financeiro, menor a necessidade de capital de giro próprio/bancário.' },
    { sub: 'Ciclo Econômico (CE)', ref: 'Análise de Capital de Giro', t: 'O Ciclo Econômico considera exclusivamente as ocorrências de natureza econômica (da compra até a venda da mercadoria, independentemente de quando ocorrem os pagamentos e recebimentos), equivalendo ao próprio Prazo Médio de Estocagem (CE = PME).', f: 'O Ciclo Econômico inicia-se no pagamento ao fornecedor e só termina na cobrança judicial do cliente inadimplente.', exp: 'Ciclo Econômico = da compra até a venda = PME.' },
    { sub: 'Necessidade de Capital de Giro (NCG) e Efeito Tesoura', ref: 'Modelo Fleuriet', t: 'Pelo Modelo Dinâmico (Fleuriet), a Necessidade de Capital de Giro (NCG) é a diferença entre o Ativo Circulante Cíclico (Operacional) e o Passivo Circulante Cíclico (Operacional); quando a NCG cresce mais rápido que o Capital de Giro permanente (CDG), ocorre o Efeito Tesoura (Saldo em Tesouraria cada vez mais negativo).', f: 'No modelo Fleuriet, o Saldo em Tesouraria (ST) é positivo sempre que a Necessidade de Capital de Giro supera o Capital de Giro permanente.', exp: 'ST = CDG - NCG. Se NCG > CDG, o Saldo em Tesouraria fica negativo (dependência de empréstimos bancários de curto prazo).' }
  ],
  28: [
    { sub: 'Arrendamento Mercantil (Leasing) na Contabilidade do Arrendatário', ref: 'CPC 06 (R2)', t: 'Pelo CPC 06 (R2), para o arrendatário deixou de existir a distinção contábil entre leasing operacional e financeiro no balanço: em regra, todo arrendamento gera o reconhecimento de um Ativo de Direito de Uso e de um Passivo de Arrendamento (exceto prazos de até 12 meses ou baixo valor).', f: 'Para o arrendatário, os arrendamentos de longo prazo de imóveis e aeronaves permanecem totalmente fora do Balanço Patrimonial.', exp: 'No CPC 06 (R2) / IFRS 16, o arrendatário reconhece no Balanço o Ativo de Direito de Uso (que sofre depreciação) e o Passivo de Arrendamento (pelo valor presente).' },
    { sub: 'Subvenção e Assistência Governamentais', ref: 'CPC 07 (R1)', t: 'Uma subvenção governamental deve ser reconhecida como receita ao longo dos períodos necessários para confrontá-la com os custos relacionados que ela pretende compensar, em base sistemática (transitando pela DRE), podendo depois ser destinada à Reserva de Incentivos Fiscais no PL.', f: 'As subvenções governamentais recebidas em terrenos ou isenções fiscais devem ser creditadas diretamente no Capital Social sem transitar pela DRE.', exp: 'Pelo CPC 07, subvenção governamental transita sempre pela DRE (como receita ou redutora da despesa) pelo regime de competência.' },
    { sub: 'Custos de Empréstimos Capitalizáveis (Ativo Qualificável)', ref: 'CPC 20 (R1)', t: 'Os custos de empréstimos que são diretamente atribuíveis à aquisição, construção ou produção de um ativo qualificável (aquele que necessariamente demanda um período substancial de tempo para ficar pronto) devem ser capitalizados como parte do custo desse ativo.', f: 'Todos os juros de capital de giro devem ser capitalizados no custo dos estoques de revenda imediata de um supermercado.', exp: 'Para empréstimos específicos, capitaliza-se o encargo incorrido menos receitas financeiras da aplicação temporária; cessa quando o ativo qualificável fica pronto.' },
    { sub: 'Ativos Biológicos e Produto Agrícola', ref: 'CPC 29', t: 'O ativo biológico (animal ou planta vivos) deve ser mensurado no reconhecimento inicial e no final de cada período pelo seu valor justo menos a despesa de venda (exceto quando o valor justo não puder ser mensurado de forma confiável), reconhecendo-se os ganhos ou perdas na DRE.', f: 'O produto agrícola colhido (como o leite ordenhado ou o café colhido) continua sendo regido indefinidamente pelo CPC 29 durante a industrialização.', exp: 'No ponto de colheita, o Produto Agrícola é mensurado ao valor justo menos despesa de venda, que passa a ser o seu custo para o CPC 16 (Estoques) dali em diante.' },
    { sub: 'Efeitos das Mudanças nas Taxas de Câmbio', ref: 'CPC 02 (R2)', t: 'No encerramento de cada balanço, os itens monetários em moeda estrangeira (caixa, contas a receber, empréstimos em dólar) são convertidos pela taxa de fechamento (reconhecendo-se a variação cambial na DRE), enquanto os itens não monetários mensurados ao custo histórico (estoques, imobilizado) permanecem pela taxa da data da transação.', f: 'O Ativo Imobilizado adquirido no exterior e avaliado ao custo histórico deve ter seu saldo reajustado mensalmente pela variação do dólar.', exp: 'Itens monetários -> taxa de fechamento; Itens não monetários ao custo histórico -> taxa histórica da data da transação.' }
  ],
  29: [
    { sub: 'Instrumentos Financeiros: Classificação de Ativos Financeiros', ref: 'CPC 48 (IFRS 9)', t: 'Pelo CPC 48, os ativos financeiros são classificados, conforme o modelo de negócios da entidade e as características dos fluxos de caixa contratuais, em três categorias: (1) Custo Amortizado; (2) Valor Justo por meio de Outros Resultados Abrangentes (VJORA); e (3) Valor Justo por meio do Resultado (VJR).', f: 'Pelo CPC 48, todos os títulos de dívida mantidos até o vencimento têm suas oscilações diárias de mercado lançadas diretamente na DRE.', exp: 'Custo Amortizado -> juros na DRE pelo método da taxa efetiva; VJORA -> juros na DRE e ajuste a valor justo no PL (ORA); VJR -> tudo na DRE.' },
    { sub: 'Receita de Contratos com Clientes (Modelo de 5 Etapas)', ref: 'CPC 47 (IFRS 15)', t: 'O CPC 47 estrutura o reconhecimento de receita em cinco etapas: (1) identificar o contrato; (2) identificar as obrigações de desempenho; (3) determinar o preço da transação; (4) alocar o preço às obrigações de desempenho; e (5) reconhecer a receita quando (ou à medida que) cada obrigação de desempenho for satisfeita.', f: 'Se uma empresa vende um equipamento junto com um contrato de manutenção de dois anos por preço único, 100% da receita deve ser reconhecida no dia da entrega do equipamento.', exp: 'O preço da transação deve ser alocado proporcionalmente aos preços de venda individuais de cada obrigação de desempenho distinta.' },
    { sub: 'Evento Subsequente ao Período Contábil (Com Ajuste vs. Sem Ajuste)', ref: 'CPC 24', t: 'Os eventos subsequentes que evidenciam condições que já existiam na data final do balanço (ex: sentença judicial pós-balanço confirmando obrigação já existente ou falência de cliente em 31/12) exigem ajuste nas demonstrações; os que indicam condições surgidas após o balanço (ex: incêndio em janeiro) não geram ajuste, apenas nota explicativa se relevantes.', f: 'A queda generalizada na cotação de mercado das ações em bolsa ocorrida em fevereiro exige a retificação dos valores do balanço encerrado em 31 de dezembro.', exp: 'Condição já existente na data do balanço = Evento com Ajuste; Condição surgida após a data do balanço = Evento sem Ajuste (divulga em NE se material).' },
    { sub: 'Tributos sobre o Lucro: Ativo e Passivo Fiscal Diferido', ref: 'CPC 32', t: 'As diferenças temporárias tributáveis resultam em valores tributáveis no futuro e geram o reconhecimento de Passivo Fiscal Diferido, enquanto as diferenças temporárias dedutíveis (e prejuízos fiscais compensáveis, até o limite de lucros futuros prováveis) geram Ativo Fiscal Diferido.', f: 'Despesas indedutíveis permanentes (como multas fiscais punitivas) geram o reconhecimento de Ativo Fiscal Diferido no Balanço Patrimonial.', exp: 'Diferenças permanentes não geram tributo diferido; apenas diferenças temporárias e prejuízos fiscais (quando provável lucro tributável futuro) geram IR/CSLL diferidos.' },
    { sub: 'Mensuração do Valor Justo e Hierarquia (Níveis 1, 2 e 3)', ref: 'CPC 46', t: 'O CPC 46 estabelece a hierarquia de valor justo em três níveis: Nível 1 (preços cotados não ajustados em mercados ativos para ativos ou passivos idênticos), Nível 2 (informações observáveis direta ou indiretamente que não as do Nível 1) e Nível 3 (dados não observáveis baseados em premissas internas).', f: 'A cotação oficial de fechamento de uma ação na B3 é classificada como informação de Nível 3 na hierarquia de valor justo.', exp: 'Nível 1 = máxima objetividade (cotação de item idêntico em mercado ativo); Nível 3 = dados não observáveis (fluxo descontado interno).' }
  ],
  30: [
    { sub: 'Síntese FGV: Fatos Contábeis e Partidas Dobradas', ref: 'Revisão Geral Contabilidade FGV', t: 'Em qualquer lançamento contábil de 1ª, 2ª, 3ª ou 4ª fórmula, a soma dos valores debitados é sempre igual à soma dos valores creditados, de modo que um único lançamento isolado a débito sem contrapartida a crédito viola o método das partidas dobradas.', f: 'Nos fatos modificativos aumentativos, o valor creditado supera o valor debitado na exata medida do lucro apurado.', exp: 'Ainda que o PL aumente (fato modificativo), o total de débitos (ex: Caixa) é sempre idêntico ao total de créditos (ex: Receita).' },
    { sub: 'Síntese FGV: Critérios de Avaliação de Ativos (Art. 183 da LSA)', ref: 'Lei 6.404/76, Art. 183', t: 'Pela Lei 6.404/76, os direitos realizáveis no decurso do exercício subsequente são avaliados pelo valor de custo ou emissão, atualizado até o limite do valor de mercado; os estoques pelo custo ou valor realizável líquido (dos dois o menor); e o imobilizado pelo custo menos depreciação acumulada e perdas por impairment.', f: 'As obrigações em moeda estrangeira do Passivo Exigível são avaliadas pela cotação histórica da data da assinatura do contrato, sem atualização cambial.', exp: 'Obrigações, encargos e riscos conhecidos e calculáveis são atualizados até a data do balanço (Art. 184 da LSA).' },
    { sub: 'Síntese FGV: Demonstrações Obrigatórias na Lei 6.404/76 vs. CPC 26', ref: 'Lei 6.404/76, Art. 176 e CPC 26', t: 'Na literalidade da Lei 6.404/76, são demonstrações obrigatórias: BP, DLPA, DRE, DFC (dispensada para Cia. fechada com PL inferior a R$ 2 milhões) e DVA (apenas para Cia. aberta); já o CPC 26 inclui também a DMPL e a Demonstração do Resultado Abrangente (DRA).', f: 'A Demonstração das Origens e Aplicações de Recursos (DOAR) permanece obrigatória na Lei 6.404/76 para todas as sociedades anônimas.', exp: 'A DOAR deixou de ser obrigatória com a Lei 11.638/07, sendo substituída pela DFC e DVA.' },
    { sub: 'Síntese FGV: Operações com Mercadorias e Tributos', ref: 'CPC 16 e CPC 47', t: 'Na compra de mercadorias para revenda, somam-se ao custo do estoque o frete sobre compras, o seguro no transporte e os tributos não recuperáveis, deduzindo-se os tributos recuperáveis (ICMS, PIS e COFINS não cumulativos) e os descontos incondicionais obtidos.', f: 'O frete pago pelo vendedor para entregar a mercadoria vendida ao cliente integra o custo de aquisição do estoque do vendedor.', exp: 'Frete sobre compras (pago pelo comprador) = Custo do Estoque; Frete sobre vendas (pago pelo vendedor) = Despesa com Vendas na DRE.' },
    { sub: 'Síntese FGV: Equivalência Patrimonial, Impairment e Reservas', ref: 'CPC 01, CPC 18 e Lei 6.404/76', t: 'No MEP, os dividendos distribuídos pela investida reduzem o saldo do investimento sem transitar pela DRE da investidora; no teste de impairment (CPC 01), a perda sobre o goodwill nunca pode ser revertida; e no PL, a Reserva Legal é de 5% do lucro líquido até o limite obrigatório de 20% do capital social.', f: 'O ágio por expectativa de rentabilidade futura (goodwill) gerado internamente deve ser ativado e amortizado em cinco anos.', exp: 'Três pilares de prova FGV: dividendo no MEP reduz investimento; impairment de goodwill é irreversível; Reserva Legal = 5% LL (teto 20% CS).' }
  ]
};


export const CASP_LESSON_MATRIX: SubjectLessonMatrix = {
  0: [
    { sub: 'Objeto e Objetivo da CASP', ref: 'NBC TSP Estrutura Conceitual / MCASP', t: 'O objeto da Contabilidade Aplicada ao Setor Público (CASP) é o patrimônio público, e seu objetivo é fornecer informações sobre os resultados alcançados e os aspectos de natureza orçamentária, econômica, financeira e física do patrimônio para apoio à tomada de decisão, prestação de contas e instrumentalização do controle social.', f: 'O objeto da CASP restringe-se exclusivamente ao controle da execução da Lei Orçamentária Anual pelo regime de caixa.', exp: 'O objeto da CASP é o Patrimônio Público (e não apenas o orçamento).' },
    { sub: 'Campo de Aplicação da CASP (Obrigatoriedade)', ref: 'MCASP 10ª Ed.', t: 'As normas do MCASP são de observância obrigatória para todos os órgãos e entidades da administração direta e para as autarquias, fundações públicas, fundos públicos e empresas estatais dependentes; para as estatais independentes, aplicam-se apenas se determinado por lei ou órgão regulador.', f: 'As empresas estatais independentes (como Petrobras e Banco do Brasil) estão obrigadas a seguir integralmente a escrituração orçamentária do MCASP.', exp: 'Estatais dependentes -> obrigatório; Estatais não dependentes (independentes) -> facultativo/não obrigatório.' },
    { sub: 'Conceito de Empresa Estatal Dependente', ref: 'LC 101/2000 (LRF), Art. 2º, III', t: 'Empresa estatal dependente é a empresa controlada que receba do ente controlador recursos financeiros para pagamento de despesas com pessoal ou de custeio em geral ou de capital, excluídos, no último caso, aqueles provenientes de aumento de participação acionária.', f: 'Qualquer aporte da União para aumento de capital em sociedade de economia mista transforma-a automaticamente em estatal dependente.', exp: 'Se o recurso para despesa de capital vier de aumento de participação acionária, NÃO configura dependência (Art. 2º, III da LRF).' },
    { sub: 'Regime Orçamentário vs. Regime Contábil (Patrimonial)', ref: 'Lei 4.320/64, Art. 35 e MCASP', t: 'Sob o enfoque orçamentário (Art. 35 da Lei 4.320/64), pertencem ao exercício financeiro as receitas nele arrecadadas (regime de caixa) e as despesas nele legalmente empenhadas; já sob o enfoque patrimonial, as variações patrimoniais aumentativas (VPA) e diminutivas (VPD) seguem o regime de competência.', f: 'Tanto as receitas orçamentárias quanto as variações patrimoniais aumentativas são reconhecidas exclusivamente pelo regime de caixa no setor público.', exp: 'Enfoque Orçamentário = misto (caixa p/ receita, empenho p/ despesa); Enfoque Patrimonial = competência integral.' },
    { sub: 'Três Aspectos da CASP (Orçamentário, Patrimonial e Fiscal)', ref: 'MCASP', t: 'A CASP organiza-se em três aspectos distintos e complementares: o aspecto orçamentário (registro da aprovação e execução do orçamento), o aspecto patrimonial (evidenciação de ativos, passivos, VPA e VPD pelo regime de competência) e o aspecto fiscal (apuração de metas, limites e indicadores da LRF).', f: 'Com a adoção das normas internacionais (IPSAS/NBC TSP), o aspecto orçamentário foi extinto e substituído pelo aspecto meramente gerencial.', exp: 'Os três aspectos (Orçamentário, Patrimonial e Fiscal) coexistem de forma integrada no PCASP.' }
  ],
  1: [
    { sub: 'Classificação da Despesa por Natureza (Categorias Econômicas e Grupos)', ref: 'Portaria Interministerial 163/2001 e MCASP', t: 'Quanto à categoria econômica, a despesa orçamentária divide-se em Despesas Correntes (código 3: Pessoal e Encargos, Juros e Encargos da Dívida, Outras Despesas Correntes) e Despesas de Capital (código 4: Investimentos, Inversões Financeiras e Amortização da Dívida).', f: 'O pagamento de juros e encargos da dívida pública classifica-se na categoria econômica de Despesas de Capital.', exp: 'Juros e encargos da dívida = Despesa Corrente (GND 2); Amortização do principal da dívida = Despesa de Capital (GND 6).' },
    { sub: 'Investimentos vs. Inversões Financeiras', ref: 'Lei 4.320/64, Art. 12, §§ 4º e 5º', t: 'Classificam-se como Investimentos o planejamento e a execução de obras, bem como a aquisição de instalações, equipamentos e material permanente (e imóveis necessários à realização de obras); já a aquisição de imóveis ou bens de capital já em utilização classifica-se como Inversão Financeira.', f: 'A compra de um edifício já construído e em plena utilização para sediar uma secretaria estadual classifica-se como Investimento.', exp: 'Imóvel para obra = Investimento; Imóvel já em utilização = Inversão Financeira (assim como constituição/aumento de capital de empresas).' },
    { sub: 'Estágios da Despesa Orçamentária (Fixação, Empenho, Liquidação e Pagamento)', ref: 'Lei 4.320/64, Arts. 58 a 64', t: 'Na execução da despesa orçamentária, o Empenho cria para o Estado obrigação de pagamento pendente ou não de implemento de condição; a Liquidação verifica o direito adquirido pelo credor tendo por base os títulos e documentos comprobatórios; e o Pagamento consiste na entrega de numerário após regular liquidação.', f: 'A liquidação da despesa precede a emissão da nota de empenho e independe da entrega do material ou prestação do serviço.', exp: 'Ordem rigorosa da execução da despesa: Empenho (Ordinário, Estimativo ou Global) -> Liquidação -> Pagamento.' },
    { sub: 'Restos a Pagar Processados vs. Não Processados', ref: 'Lei 4.320/64, Art. 36 e MCASP', t: 'Consideram-se Restos a Pagar as despesas empenhadas mas não pagas até 31 de dezembro, distinguindo-se as processadas (que já passaram pelo estágio da liquidação) das não processadas (empenhadas, mas ainda pendentes de liquidação).', f: 'Os Restos a Pagar Processados podem ser livremente cancelados por conveniência administrativa, pois o fornecedor ainda não entregou o bem.', exp: 'Nos RP Processados, o credor já cumpriu sua obrigação (despesa liquidada), constituindo direito adquirido que em regra não pode ser cancelado.' },
    { sub: 'Despesas de Exercícios Anteriores (DEA) e Suprimento de Fundos', ref: 'Lei 4.320/64, Art. 37 e 68', t: 'As Despesas de Exercícios Anteriores (DEA) atendem a compromissos cujo empenho foi insubsistente/cancelado ou a obrigações criadas em virtude de lei reconhecidas após o encerramento, onerando a dotação do orçamento vigente; já o Suprimento de Fundos é adiantamento precedido de empenho na dotação própria.', f: 'Pode-se conceder suprimento de fundos a servidor declarado em alcance ou que já seja responsável por dois adiantamentos sem prestação de contas.', exp: 'Art. 69 da Lei 4.320/64: não se fará adiantamento a servidor em alcance nem a responsável por dois adiantamentos.' }
  ],
  2: [
    { sub: 'Ativo Imobilizado no Setor Público: Bens de Uso Comum do Povo', ref: 'MCASP e NBC TSP 07', t: 'Os bens de uso comum do povo (como praças, rodovias e pontes - ativos de infraestrutura) passaram a ter reconhecimento obrigatório no Ativo Imobilizado do ente público, devendo ser depreciados ao longo de sua vida útil.', f: 'Os bens de uso comum do povo (rodovias e viadutos) são proibidos de figurar no Balanço Patrimonial do ente público.', exp: 'Com a convergência às IPSAS (NBC TSP 07 e MCASP), os bens de uso comum do povo / ativos de infraestrutura integram o Ativo Imobilizado.' },
    { sub: 'Ativos Culturais (Heritage Assets)', ref: 'NBC TSP 07 e MCASP', t: 'Alguns ativos são descritos como ativos culturais (bens do patrimônio histórico, artístico ou cultural, como monumentos e obras de arte); se atenderem aos critérios de reconhecimento de ativo imobilizado e puderem ser mensurados com confiabilidade, são reconhecidos, caso contrário divulgam-se em notas explicativas.', f: 'Todo monumento histórico tombado sofre depreciação acelerada obrigatória em cinco anos no setor público.', exp: 'Ativos culturais com vida útil indefinida não são depreciados; se não puderem ser mensurados de modo confiável, são evidenciados em notas explicativas.' },
    { sub: 'Mensuração de Ativo Obtido por Transação Sem Contraprestação', ref: 'NBC TSP 07', t: 'Quando um ativo imobilizado é adquirido por meio de uma transação sem contraprestação (como doação ou confisco), seu custo no reconhecimento inicial deve ser mensurado pelo seu valor justo na data da aquisição.', f: 'Bens recebidos em doação por órgãos públicos devem ser registrados pelo valor simbólico fixo de R$ 1,00, independentemente do valor de mercado.', exp: 'Na aquisição sem contraprestação (doação), o ativo é reconhecido pelo Valor Justo na data do recebimento contra uma VPA.' },
    { sub: 'Reavaliação de Ativos no Setor Público (Diferença em relação ao Setor Privado)', ref: 'NBC TSP 07 e MCASP', t: 'Diferentemente da contabilidade societária privada (onde a reavaliação é vedada pela Lei 11.638/07), no setor público brasileiro é expressamente permitida a adoção do modelo da reavaliação ao valor justo para mensuração subsequente do Ativo Imobilizado e Intangível.', f: 'A reavaliação de bens imóveis públicos a valor justo é crime de responsabilidade fiscal expressamente proibido pelo MCASP.', exp: 'Atenção máxima em prova: Setor Privado = reavaliação proibida; Setor Público (CASP) = reavaliação permitida!' },
    { sub: 'Redução ao Valor Recuperável (Impairment) de Ativos Não Geradores de Caixa', ref: 'NBC TSP 09 e NBC TSP 10', t: 'No setor público, distinguem-se os ativos geradores de caixa (mantidos com objetivo comercial) e os ativos não geradores de caixa (mantidos para prestação gratuita ou subsidiada de serviços públicos, como escolas e hospitais), cujo valor em uso equivale ao valor presente do potencial de serviços remanescente.', f: 'Escolas públicas gratuitas não podem sofrer teste de redução ao valor recuperável por não cobrarem mensalidade dos alunos.', exp: 'NBC TSP 09 trata do impairment de ativos não geradores de caixa (baseado no potencial de serviços), e NBC TSP 10 dos geradores de caixa.' }
  ],
  3: [
    { sub: 'Ativo Intangível no Setor Público', ref: 'NBC TSP 08 e MCASP', t: 'No setor público, o ativo intangível é um ativo não monetário identificável sem substância física (como softwares adquiridos ou desenvolvidos internamente); os gastos da fase de pesquisa são reconhecidos como VPD (despesa patrimonial) e os da fase de desenvolvimento são ativados se atendidos os critérios.', f: 'No setor público, tanto os gastos da fase de pesquisa quanto o treinamento de servidores são capitalizados no Ativo Intangível.', exp: 'Tal como no setor privado, pesquisa = VPD (despesa); desenvolvimento = Ativo Intangível (se demonstrada viabilidade técnica/potencial de serviços).' },
    { sub: 'Provisões, Passivos Contingentes e Ativos Contingentes no Setor Público', ref: 'NBC TSP 03 e MCASP', t: 'Segundo a NBC TSP 03, uma provisão é reconhecida no passivo quando há obrigação presente (legal ou não formalizada), saída provável de recursos e estimativa confiável; já os passivos contingentes não são reconhecidos no balanço, sendo divulgados em notas explicativas (salvo se remotos).', f: 'No setor público, qualquer ação judicial ajuizada contra a Fazenda Pública é imediatamente reconhecida no Passivo Circulante pelo valor da causa, mesmo que o risco seja remoto.', exp: 'A regra da NBC TSP 03 é idêntica ao CPC 25: Provável = Provisão no Balanço; Possível = Nota Explicativa; Remota = nada.' },
    { sub: 'Receita de Transação Sem Contraprestação (Tributos e Transferências)', ref: 'NBC TSP 01 e MCASP', t: 'Os tributos e as transferências intergovernamentais são as principais transações sem contraprestação do setor público: o ativo e a correspondente VPA são reconhecidos quando ocorre o evento tributável (fato gerador) e o recurso passa ao controle da entidade com mensuração confiável.', f: 'Na CASP, os créditos tributários lançados pela Fazenda Estadual jamais podem ser reconhecidos como Ativo Patrimonial antes do pagamento em dinheiro pelo contribuinte.', exp: 'Sob o enfoque patrimonial (NBC TSP 01), o lançamento tributário / ocorrência do fato gerador mensurável reconhece o Crédito Tributário a Receber (Ativo) e a VPA.' },
    { sub: 'Ajuste para Perdas em Créditos e Dívida Ativa', ref: 'MCASP', t: 'Os créditos inscritos em Dívida Ativa (Tributária e Não Tributária) integram o Ativo do ente público e devem ser ajustados por conta retificadora de Ajuste para Perdas da Dívida Ativa, estimada com base no histórico de recebimento e recuperabilidade.', f: 'A inscrição de um crédito em Dívida Ativa implica a sua baixa definitiva do Ativo Patrimonial por presunção de insolvência.', exp: 'A Dívida Ativa é um direito (Ativo Circulante ou Não Circulante) sujeito a Ajuste para Perdas (conta retificadora).' },
    { sub: 'Benefícios a Empregados e Passivo Atuarial (RPPS)', ref: 'NBC TSP 15 e MCASP', t: 'As obrigações decorrentes de benefícios pós-emprego dos servidores vinculados ao Regime Próprio de Previdência Social (RPPS) devem ter sua provisão matemática previdenciária (passivo atuarial) reconhecida no Balanço Patrimonial pelo regime de competência.', f: 'O passivo atuarial dos Regimes Próprios de Previdência Social (RPPS) é registrado apenas em contas de controle orçamentário, sem afetar o Patrimônio Líquido.', exp: 'A provisão matemática previdenciária (passivo atuarial do RPPS) compõe o Passivo Não Circulante sob a ótica patrimonial.' }
  ],
  4: [
    { sub: 'Estrutura das 8 Classes do PCASP', ref: 'MCASP - Parte IV (PCASP)', t: 'O Plano de Contas Aplicado ao Setor Público (PCASP) está estruturado em 8 classes agrupadas em três naturezas de informação: Patrimonial (1-Ativo, 2-Passivo e PL, 3-VPD, 4-VPA), Orçamentária (5-Controles da Aprovação do Planejamento e Orçamento, 6-Controles da Execução do Planejamento e Orçamento) e Controle (7-Controles Devedores, 8-Controles Credores).', f: 'No PCASP, as classes 1 e 2 registram a aprovação e a execução da Lei Orçamentária Anual.', exp: 'Classes 1 a 4 = Natureza Patrimonial; Classes 5 e 6 = Natureza Orçamentária; Classes 7 e 8 = Natureza de Controle.' },
    { sub: 'Regra de Fechamento das Partidas Dobradas por Natureza de Informação', ref: 'MCASP - PCASP', t: 'No PCASP, os lançamentos contábeis são fechados dentro da mesma natureza de informação: um débito em conta de natureza patrimonial (classes 1 a 4) só pode ter como contrapartida um crédito em conta também de natureza patrimonial (classes 1 a 4), sendo vedado debitar classe 1 e creditar classe 6.', f: 'Na arrecadação de uma receita de ICMS, debita-se a conta Caixa (Classe 1) diretamente em contrapartida a crédito de Receita Realizada (Classe 6).', exp: 'Nunca se misturam naturezas diferentes no mesmo lançamento! Na arrecadação, faz-se 1 lançamento patrimonial (1/4), 1 orçamentário (6/6) e 1 de controle (7/8).' },
    { sub: 'Atributos da Conta Contábil para o Superávit Financeiro (F e P)', ref: 'MCASP - PCASP', t: 'Para viabilizar o cálculo do Superávit Financeiro no Balanço Patrimonial (Art. 43, §2º da Lei 4.320/64), os ativos e passivos das classes 1 e 2 possuem o indicador de superávit financeiro: atributo (F) para Financeiro (independe de autorização orçamentária) e atributo (P) para Permanente (depende de autorização orçamentária).', f: 'O atributo (P) identifica os passivos financeiros já empenhados que independem de autorização legislativa para pagamento.', exp: 'Atributo F = Ativo/Passivo Financeiro; Atributo P = Ativo/Passivo Permanente. No empenho/liquidação, o passivo troca de P para F!' },
    { sub: 'Codificação das Contas do PCASP (7 Níveis)', ref: 'MCASP - PCASP', t: 'A codificação das contas no PCASP possui 7 níveis de desdobramento (X.X.X.X.X.XX.XX): 1º Classe, 2º Grupo, 3º Subgrupo, 4º Título, 5º Subtítulo (que identifica a consolidação: 1-Intra, 2-Inter Uniao/Est/Mun, etc.), 6º Item e 7º Subitem.', f: 'O código do PCASP possui apenas três dígitos fixos sem distinção para transações intraorçamentárias ou intergovernamentais.', exp: 'O 5º nível (Subtítulo) do código do PCASP é fundamental para a consolidação nacional (Siconfi): 1=Consolidação (Intra), 2=Inter OFSS Mesmo Ente, 3/4/5=Inter OFSS União/Estado/Município.' },
    { sub: 'Lançamentos Típicos de Empenho, Liquidação e Pagamento no PCASP', ref: 'MCASP - PCASP', t: 'No momento da liquidação de despesa de serviço, ocorrem lançamentos simultâneos: na natureza orçamentária (D - 6.2.2.1.3.01 Empenho em Liquidação / C - 6.2.2.1.3.03 Empenho Liquidado a Pagar); na patrimonial (se ainda não reconhecido o fato gerador: D - Classe 3 VPD / C - Classe 2 Passivo P) e a transferência do Passivo de (P) para (F).', f: 'No momento do empenho da despesa, já se reconhece obrigatoriamente a Variação Patrimonial Diminutiva (Classe 3) em todos os contratos.', exp: 'O empenho é ato orçamentário (Classes 5/6) e de controle (Classes 7/8); a VPD (Classe 3) ocorre pelo fato gerador (em regra antes ou na liquidação).' }
  ],
  5: [
    { sub: 'Finalidade e Estrutura do Balanço Orçamentário (BO)', ref: 'Lei 4.320/64, Art. 102 e MCASP', t: 'O Balanço Orçamentário demonstrará as receitas e despesas previstas em confronto com as realizadas, evidenciando o resultado orçamentário do exercício (superávit ou déficit orçamentário), além dos quadros anexos de execução de restos a pagar não processados e processados.', f: 'O Balanço Orçamentário compara o Ativo Imobilizado com as Variações Patrimoniais Diminutivas pelo regime de competência.', exp: 'Art. 102 da Lei 4.320/64: BO confronta Receitas Previstas vs. Realizadas (arrecadadas) e Despesas Fixadas vs. Executadas (empenhadas, liquidadas e pagas).' },
    { sub: 'Cálculo do Resultado Orçamentário do Exercício', ref: 'MCASP - Parte V (DCASP)', t: 'No Balanço Orçamentário, o Resultado Orçamentário do período é apurado pela diferença entre a Receita Orçamentária Realizada (arrecadada, líquida de deduções) e a Despesa Orçamentária Empenhada.', f: 'Para apurar o superávit ou déficit orçamentário no Balanço Orçamentário, confronta-se a receita prevista na LOA com a despesa meramente fixada.', exp: 'Resultado Orçamentário = Receita Realizada (Arrecadada) - Despesa Empenhada. Se positivo = Superávit Orçamentário; se negativo = Déficit Orçamentário.' },
    { sub: 'Economia Orçamentária vs. Superávit Orçamentário', ref: 'Doutrina AFO/CASP e MCASP', t: 'Dá-se o nome de economia orçamentária quando a despesa empenhada é inferior à dotação autorizada (créditos fixados/atualizados); já o superávit orçamentário ocorre quando a receita efetivamente arrecadada supera a despesa empenhada.', f: 'Sempre que houver economia de despesa em relação à dotação fixada, haverá necessariamente superávit orçamentário na execução.', exp: 'Pode haver economia orçamentária (gastou menos que o fixado) e ainda assim ocorrer déficit orçamentário (se a arrecadação tiver frustrado muito).' },
    { sub: 'Utilização do Superávit Financeiro e Reabertura de Créditos no BO', ref: 'MCASP - Parte V', t: 'No quadro principal do Balanço Orçamentário, as linhas de "Saldos de Exercícios Anteriores" (utilizados como fonte para abertura de créditos adicionais: superávit financeiro do exercício anterior e créditos adicionais reabertos) são evidenciadas apenas na coluna de Previsão Atualizada, equilibrando a dotação atualizada sem inflar a Receita Realizada do ano corrente.', f: 'O superávit financeiro apurado no balanço patrimonial do ano anterior é contabilizado novamente como Receita Corrente Arrecadada no ano seguinte.', exp: 'Saldos de exercícios anteriores entram na Previsão Atualizada para equilibrar os créditos adicionais abertos, mas não são receita arrecadada de novo.' },
    { sub: 'Quadros de Execução dos Restos a Pagar no BO', ref: 'MCASP - Parte V', t: 'A execução dos Restos a Pagar (inscritos em exercícios anteriores) não integra o quadro principal das despesas orçamentárias do exercício corrente, sendo demonstrada em dois quadros específicos anexos ao Balanço Orçamentário (Execução de RP Não Processados e Execução de RP Processados).', f: 'O pagamento de Restos a Pagar no exercício seguinte é somado novamente à coluna de Despesas Empenhadas do quadro principal do Balanço Orçamentário.', exp: 'RP pertencem ao orçamento do ano em que foram empenhados; sua liquidação/pagamento nos anos seguintes aparece nos quadros anexos do BO e no Balanço Financeiro.' }
  ],
  6: [
    { sub: 'Finalidade e Equação do Balanço Financeiro (BF)', ref: 'Lei 4.320/64, Art. 103 e MCASP', t: 'O Balanço Financeiro demonstra as receitas e despesas orçamentárias, bem como os ingressos e dispêndios extraorçamentários, conjugados com os saldos em espécie provenientes do exercício anterior e os que se transferem para o exercício seguinte.', f: 'O Balanço Financeiro inclui apenas as receitas correntes e exclui todas as cauções, depósitos de terceiros e retenções em folha.', exp: 'Art. 103 da Lei 4.320/64: Saldo Inicial + Receitas Orçamentárias + Ingressos Extraorçamentários = Despesas Orçamentárias + Dispêndios Extraorçamentários + Saldo Final.' },
    { sub: 'Inscrição de Restos a Pagar como Ingresso Extraorçamentário no BF', ref: 'Lei 4.320/64, Art. 103, par. único', t: 'No Balanço Financeiro, a despesa orçamentária é computada pelo valor empenhado; por isso, os Restos a Pagar inscritos no exercício são obrigatoriamente computados na coluna de Receita Extraorçamentária (Ingressos Extraorçamentários) para compensar o valor empenhado e não pago.', f: 'No Balanço Financeiro, a inscrição de Restos a Pagar do exercício figura apenas no lado dos dispêndios para reduzir o saldo de caixa.', exp: 'Regra clássica do Art. 103, parágrafo único da Lei 4.320/64: como a Despesa Orçamentária entra pelo total empenhado, os RP inscritos entram como Ingresso Extraorçamentário para anular a saída que ainda não ocorreu!' },
    { sub: 'Pagamento de Restos a Pagar no Balanço Financeiro', ref: 'MCASP - Parte V', t: 'O pagamento, no exercício corrente, de Restos a Pagar inscritos em exercícios anteriores configura um Dispêndio Extraorçamentário no Balanço Financeiro.', f: 'O pagamento de Restos a Pagar de anos anteriores é classificado como Despesa Orçamentária Corrente no Balanço Financeiro do ano do pagamento.', exp: 'Inscrição de RP no ano = Ingresso Extraorçamentário; Pagamento de RP em anos seguintes = Dispêndio Extraorçamentário.' },
    { sub: 'Transferências Financeiras Recebidas e Concedidas no BF', ref: 'MCASP - Parte V', t: 'O Balanço Financeiro evidencia as Transferências Financeiras Recebidas e as Transferências Financeiras Concedidas (como cotas, repasses e sub-repasses decorrentes ou independentes da execução orçamentária, inclusive duodécimos aos Poderes e aportes para cobertura do RPPS).', f: 'Os repasses de duodécimos do Poder Executivo ao Poder Legislativo são contabilizados como Receita Tributária Orçamentária da Assembleia.', exp: 'Cotas, repasses e sub-repasses (como duodécimos) são Transferências Financeiras (não são receita orçamentária nova do Legislativo), destacadas no BF.' },
    { sub: 'Apuração do Resultado Financeiro do Exercício no BF', ref: 'MCASP - Parte V', t: 'O Resultado Financeiro do Exercício apurado no Balanço Financeiro equivale exatamente à variação do saldo em espécie (Caixa e Equivalentes de Caixa): Saldo em Espécie para o Exercício Seguinte menos Saldo em Espécie do Exercício Anterior.', f: 'O Resultado Financeiro do Balanço Financeiro é sempre idêntico ao Superávit Financeiro apurado no Balanço Patrimonial.', exp: 'Cuidado! Resultado Financeiro do Exercício (no BF) = Variação de Caixa (Saldo Final - Saldo Inicial). Já o Superávit Financeiro (no BP) = Ativo Financeiro - Passivo Financeiro!' }
  ],
  7: [
    { sub: 'Estrutura do Balanço Patrimonial Público (Quadro Principal e Quadros Anexos)', ref: 'MCASP - Parte V', t: 'Conforme o MCASP, o Balanço Patrimonial é composto por: (1) Quadro Principal (Ativo Circulante/Não Circulante e Passivo Circulante/Não Circulante + Patrimônio Líquido, segundo a natureza patrimonial); (2) Quadro dos Ativos e Passivos Financeiros e Permanentes (Lei 4.320/64); (3) Quadro das Contas de Compensação (Controle); e (4) Quadro do Superávit/Déficit Financeiro.', f: 'No novo modelo do MCASP, o Quadro dos Ativos e Passivos Financeiros e Permanentes foi abolido em definitivo.', exp: 'O MCASP concilia a norma internacional (Quadro Principal: Circulante / Não Circulante) com a Lei 4.320/64 (Quadro Anexo: Financeiro / Permanente).' },
    { sub: 'Ativo Financeiro vs. Ativo Permanente (Art. 105 da Lei 4.320/64)', ref: 'Lei 4.320/64, Art. 105, §§ 1º e 2º', t: 'No quadro anexo da Lei 4.320/64, o Ativo Financeiro (atributo F) compreenderá os créditos e valores realizáveis independentemente de autorização orçamentária e os valores numerários; e o Ativo Permanente (atributo P) compreenderá os bens, créditos e valores cuja mobilização ou alienação dependa de autorização legislativa.', f: 'Os créditos tributários de IPTU e ICMS inscritos em Dívida Ativa integram o Ativo Financeiro para fins de cálculo do superávit financeiro.', exp: 'Dívida Ativa, Estoques e Bens Móveis/Imóveis têm atributo (P) - Ativo Permanente. Caixa e aplicações de liquidez imediata têm atributo (F) - Ativo Financeiro.' },
    { sub: 'Passivo Financeiro vs. Passivo Permanente (Art. 105 da Lei 4.320/64)', ref: 'Lei 4.320/64, Art. 105, §§ 3º e 4º', t: 'O Passivo Financeiro (atributo F) compreenderá as dívidas fundadas e outras cujo pagamento independa de autorização orçamentária (como Restos a Pagar inscritos e consignações/depósitos de terceiros); o Passivo Permanente (atributo P) compreenderá as dívidas fundadas e outras que dependam de autorização legislativa para amortização ou resgate.', f: 'Os empréstimos de longo prazo (dívida fundada) que ainda não foram empenhados integram o Passivo Financeiro desde a assinatura do contrato.', exp: 'Passivo antes do empenho = atributo (P) Passivo Permanente; após o empenho (Restos a Pagar) ou extraorçamentário (depósitos/cauções) = atributo (F) Passivo Financeiro.' },
    { sub: 'Cálculo do Superávit Financeiro no Balanço Patrimonial', ref: 'Lei 4.320/64, Art. 43, §2º', t: 'Entende-se por Superávit Financeiro a diferença positiva entre o Ativo Financeiro e o Passivo Financeiro (SF = AF - PF), conjugando-se, ainda, os saldos dos créditos adicionais transferidos (reabertos) e as operações de crédito a eles vinculadas.', f: 'O Superávit Financeiro é calculado pela diferença entre o Ativo Circulante e o Passivo Circulante do Quadro Principal.', exp: 'Fórmula clássica do Art. 43, §2º: Superávit Financeiro = Ativo Financeiro (F) - Passivo Financeiro (F) - Créditos Adicionais Reabertos + Operações de Crédito Vinculadas.' },
    { sub: 'Superávit Financeiro por Fonte/Destinação de Recursos', ref: 'MCASP e LRF (Art. 8º, par. único)', t: 'O Quadro do Superávit/Déficit Financeiro do Balanço Patrimonial deve segregar o saldo apurado por Fonte/Destinação de Recursos (recursos ordinários/livres vs. recursos vinculados), pois os recursos legalmente vinculados a finalidade específica serão utilizados exclusivamente para atender ao objeto de sua vinculação, ainda que em exercício diverso.', f: 'Um superávit financeiro apurado na fonte vinculada do Fundeb pode ser livremente utilizado para abrir crédito suplementar para construir um presídio.', exp: 'Art. 8º, parágrafo único da LRF: o superávit financeiro de fonte vinculada só pode abrir crédito adicional para a mesma finalidade da vinculação!' }
  ],
  8: [
    { sub: 'Finalidade da Demonstração das Variações Patrimoniais (DVP)', ref: 'Lei 4.320/64, Art. 104 e MCASP', t: 'A Demonstração das Variações Patrimoniais (DVP) evidenciará as alterações verificadas no patrimônio, resultantes ou independentes da execução orçamentária, e indicará o resultado patrimonial do exercício (equivalendo, no setor público, à DRE da contabilidade societária).', f: 'A DVP apura o resultado financeiro pelo regime de caixa, somando os ingressos extraorçamentários de cauções.', exp: 'Resultado Patrimonial (na DVP) = Total das Variações Patrimoniais Aumentativas (VPA - Classe 4) menos Total das Variações Patrimoniais Diminutivas (VPD - Classe 3).' },
    { sub: 'Variações Patrimoniais Quantitativas vs. Qualitativas', ref: 'MCASP', t: 'As variações patrimoniais são transações que promovem alterações nos elementos patrimoniais da entidade do setor público e classificam-se em quantitativas (aquelas que aumentam ou diminuem o Patrimônio Líquido: VPA e VPD, transitando pela DVP) e qualitativas (permutativas entre Ativo e/ou Passivo, que não alteram o PL e não figuram na DVP no modelo MCASP).', f: 'A compra à vista de um veículo para a frota oficial reduz o Patrimônio Líquido na DVP no ato da aquisição.', exp: 'No modelo atual do MCASP, a DVP evidencia apenas as variações quantitativas (VPA e VPD); a compra de veículo é variação qualitativa/permutativa (+Veículos, -Caixa).' },
    { sub: 'Exemplos de VPA (Classe 4 do PCASP)', ref: 'MCASP - Parte V', t: 'Constituem grupos de Variações Patrimoniais Aumentativas (VPA) na DVP: Impostos, Taxas e Contribuições de Melhoria; Contribuições; Exploração e Venda de Bens, Serviços e Direitos; Variações Patrimoniais Aumentativas Financeiras; Transferências e Delegações Recebidas; e Valorização e Ganhos com Ativos e Desincorporação de Passivos (ex: doação recebida ou prescrição de dívida).', f: 'O recebimento de um empréstimo bancário de longo prazo é classificado como Variação Patrimonial Aumentativa (VPA) na DVP.', exp: 'Empréstimo recebido é receita orçamentária de capital (mutação/permutativa), mas NÃO é VPA porque gera um Passivo de igual valor (+Caixa, +Empréstimos a Pagar).' },
    { sub: 'Exemplos de VPD (Classe 3 do PCASP)', ref: 'MCASP - Parte V', t: 'Constituem grupos de Variações Patrimoniais Diminutivas (VPD) na DVP: Pessoal e Encargos; Benefícios Previdenciários e Assistenciais; Uso de Bens, Serviços e Consumo de Capital Fixo (depreciação, amortização e exaustão); VPD Financeiras; Transferências e Delegações Concedidas; e Desvalorizações e Perdas de Ativos e Incorporação de Passivos.', f: 'A amortização do principal da dívida pública contratual constitui Variação Patrimonial Diminutiva (VPD) na DVP.', exp: 'Amortizar o principal da dívida é despesa orçamentária de capital (efetiva/não efetiva -> mutação/permutativa: -Caixa, -Passivo), logo NÃO é VPD! Já os juros e a depreciação SÃO VPD.' },
    { sub: 'Transferência do Resultado Patrimonial para o Balanço Patrimonial', ref: 'MCASP - Parte V', t: 'O Resultado Patrimonial do período (Superávit ou Déficit Patrimonial), apurado na última linha da DVP pelo confronto entre VPA e VPD, é transferido diretamente para a conta Resultados Acumulados no Patrimônio Líquido do Balanço Patrimonial.', f: 'O Superávit Patrimonial apurado na DVP serve diretamente como fonte financeira para abertura de créditos suplementares na LOA.', exp: 'Cuidado: o que abre crédito adicional é o Superávit FINANCEIRO (do BP), e não o Superávit Patrimonial (da DVP)!' }
  ],
  9: [
    { sub: 'Método de Elaboração da DFC no Setor Público', ref: 'MCASP - Parte V e NBC TSP 12', t: 'Diferentemente do setor privado (que admite os métodos direto e indireto), o MCASP padronizou a elaboração da Demonstração dos Fluxos de Caixa (DFC) no setor público exclusivamente pelo Método Direto, detalhando os ingressos e desembolsos brutos nas atividades operacionais, de investimento e de financiamento.', f: 'No setor público brasileiro, o MCASP proíbe o método direto na DFC, exigindo exclusivamente o método indireto a partir do superávit patrimonial.', exp: 'No MCASP, a DFC pública é elaborada pelo Método Direto (com conciliação em nota explicativa).' },
    { sub: 'Classificação dos Fluxos na DFC Pública (Operacional, Investimento e Financiamento)', ref: 'MCASP - Parte V', t: 'Na DFC do setor público: (1) Atividades Operacionais compreendem a arrecadação tributária, transferências correntes/de capital recebidas e pagamentos de pessoal, custeio e juros da dívida; (2) Atividades de Investimento compreendem aquisição e alienação de ativo não circulante (imobilizado, intangível, participações); e (3) Atividades de Financiamento compreendem a captação (empréstimos) e a amortização/refinanciamento do principal da dívida pública.', f: 'O pagamento dos juros e encargos da dívida pública é classificado no fluxo das atividades de investimento da DFC pública.', exp: 'Atenção FGV na DFC Pública (MCASP): Juros da dívida pagos = Fluxo Operacional; Amortização do principal da dívida = Fluxo de Financiamento!' },
    { sub: 'Obrigatoriedade da DMPL no Setor Público', ref: 'MCASP - Parte V', t: 'Segundo o MCASP, a Demonstração das Mutações do Patrimônio Líquido (DMPL) é obrigatória apenas para as empresas estatais dependentes e para os entes que as incorporarem no processo de consolidação das contas públicas, sendo facultativa para os demais órgãos da administração direta.', f: 'A DMPL é proibida para as empresas estatais dependentes constituídas sob a forma de sociedade anônima.', exp: 'Como as estatais dependentes são S.A. regidas também pela Lei 6.404/76, a DMPL é obrigatória para elas e para o ente controlador que as consolida.' },
    { sub: 'Itens Evidenciados na DMPL Pública', ref: 'MCASP - Parte V', t: 'A DMPL evidencia a movimentação de todas as contas do Patrimônio Líquido do ente público durante o exercício, incluindo o Patrimônio Social/Capital Social, os Ajustes de Avaliação Patrimonial, as Reservas, os Resultados Acumulados e os Ajustes de Exercícios Anteriores (mudança de política contábil e retificação de erro).', f: 'A DMPL pública demonstra exclusivamente a execução dos Restos a Pagar Não Processados do exercício.', exp: 'A DMPL detalha em colunas cada conta da Classe 2.3 (Patrimônio Líquido) do PCASP.' },
    { sub: 'Notas Explicativas às Demonstrações Contábeis (DCASP)', ref: 'MCASP - Parte V e NBC TSP 11', t: 'As Notas Explicativas são parte integrante das Demonstrações Contábeis Aplicadas ao Setor Público (DCASP) e contêm informações adicionais em relação àquelas apresentadas no corpo das demonstrações, incluindo a declaração de conformidade com a legislação e normas, o resumo das políticas contábeis significativas e informações de suporte aos itens apresentados.', f: 'A publicação de Notas Explicativas no setor público dispensa o ente federado de elaborar o Balanço Patrimonial e o Balanço Orçamentário.', exp: 'Notas Explicativas integram o conjunto completo das DCASP, complementando (mas jamais substituindo) as demonstrações.' }
  ],
  10: [
    { sub: 'Abrangência e Organização da Contabilidade Pública na Lei 4.320/64', ref: 'Lei 4.320/64, Arts. 83 a 89', t: 'Nos termos do Título IX da Lei 4.320/64, a contabilidade evidenciará perante a Fazenda Pública a situação de todos quantos, de qualquer modo, arrecadem receitas, efetuem despesas, administrem ou guardem bens a ela pertencentes ou confiados, sendo organizada pelo método das partidas dobradas.', f: 'A Lei 4.320/64 determina que a escrituração contábil dos municípios seja feita pelo método das partidas simples.', exp: 'Art. 86 da Lei 4.320/64: a escrituração sintética das operações financeiras e patrimoniais efetuar-se-á pelo método das partidas dobradas.' },
    { sub: 'Controle dos Direitos e Obrigações Oriundos de Contratos e Convênios', ref: 'Lei 4.320/64, Art. 87', t: 'Haverá controle contábil dos direitos e obrigações oriundos de ajustes ou contratos em que a administração pública for parte, os quais são escriturados em contas de compensação/controle (Classes 7 e 8 do PCASP).', f: 'Segundo o Art. 87 da Lei 4.320/64, os contratos administrativos em andamento não devem ter qualquer registro de controle na contabilidade.', exp: 'Atos potenciais (contratos, convênios, garantias, avais) têm controle contábil obrigatório (Art. 87 da Lei 4.320/64).' },
    { sub: 'Contabilidade Analítica dos Bens Móveis, Imóveis e Almoxarifados', ref: 'Lei 4.320/64, Arts. 94 a 96', t: 'Haverá registros analíticos de todos os bens de caráter permanente, com indicação dos elementos necessários para a perfeita caracterização de cada um e dos agentes responsáveis pela sua guarda e administração, mantendo a contabilidade registros sintéticos dos bens móveis e imóveis.', f: 'O levantamento geral dos bens móveis e imóveis terá por base apenas a estimativa verbal do prefeito, dispensado o inventário analítico.', exp: 'Art. 96 da Lei 4.320/64: o levantamento geral dos bens móveis e imóveis terá por base o inventário analítico de cada unidade administrativa e os elementos da escrituração sintética na contabilidade.' },
    { sub: 'Quatro Demonstrações da Lei 4.320/64 (Art. 101)', ref: 'Lei 4.320/64, Art. 101', t: 'Na redação original do Art. 101 da Lei 4.320/64, os resultados gerais do exercício serão demonstrados no Balanço Orçamentário, no Balanço Financeiro, no Balanço Patrimonial e na Demonstração das Variações Patrimoniais, além dos quadros demonstrativos anexos.', f: 'O Art. 101 da Lei 4.320/64 instituiu originalmente a Demonstração do Valor Adicionado (DVA) para todas as prefeituras.', exp: 'Na Lei 4.320/64 são 4 demonstrações: BO, BF, BP e DVP. O MCASP/NBC TSP acrescentaram a DFC, a DMPL e as Notas Explicativas.' },
    { sub: 'Avaliação dos Elementos Patrimoniais na Lei 4.320/64 (Art. 106)', ref: 'Lei 4.320/64, Art. 106', t: 'Pela literalidade do Art. 106 da Lei 4.320/64: os débitos e créditos, bem como os títulos de renda, são avaliados pelo seu valor nominal (feita a conversão, quando em moeda estrangeira, à taxa de câmbio vigente na data do balanço); os bens móveis e imóveis, pelo valor de aquisição ou pelo custo de produção ou de construção; e os bens de almoxarifado, pelo preço médio ponderado das compras.', f: 'Pela literalidade do Art. 106 da Lei 4.320/64, os bens de almoxarifado devem ser avaliados exclusivamente pelo critério UEPS.', exp: 'Art. 106, III da Lei 4.320/64: bens de almoxarifado = preço médio ponderado das compras.' }
  ],
  11: [
    { sub: 'Usuários Primários dos Relatórios Contábeis de Propósito Geral (RCPGs)', ref: 'NBC TSP Estrutura Conceitual', t: 'Segundo a NBC TSP Estrutura Conceitual, os usuários primários dos Relatórios Contábeis de Propósito Geral das Entidades do Setor Público (RCPGs) são os usuários dos serviços e seus representantes (Poder Legislativo) e os provedores de recursos e seus representantes (contribuintes, credores, doadores).', f: 'Os usuários primários dos RCPGs no setor público são exclusivamente os auditores internos e os ministros de Estado.', exp: 'Usuários primários na NBC TSP EC: (1) Usuários dos serviços + (2) Provedores de recursos (e seus representantes no Legislativo).' },
    { sub: 'Características Qualitativas na NBC TSP Estrutura Conceitual', ref: 'NBC TSP Estrutura Conceitual, Cap. 3', t: 'Diferentemente do CPC 00 (que divide as características em fundamentais e de melhoria), a NBC TSP Estrutura Conceitual apresenta um conjunto único de 6 características qualitativas da informação nos RCPGs: Relevância, Representação Fidedigna, Compreensibilidade, Tempestividade, Comparabilidade e Verificabilidade.', f: 'A NBC TSP Estrutura Conceitual classifica a Materialidade e o Custo-Benefício como características qualitativas de melhoria.', exp: 'Pegadinha clássica FGV! Na NBC TSP EC: são 6 características qualitativas (sem dividir em fundamentais/melhoria), e Materialidade, Custo-Benefício e Alcance do Equilíbrio são RESTRIÇÕES à informação!' },
    { sub: 'Definição de Ativo na NBC TSP Estrutura Conceitual', ref: 'NBC TSP Estrutura Conceitual, Cap. 5', t: 'Na NBC TSP Estrutura Conceitual, Ativo é um recurso controlado no presente pela entidade como resultado de evento passado, sendo "recurso" um item com potencial de serviços ou com a capacidade de gerar benefícios econômicos.', f: 'Na NBC TSP Estrutura Conceitual, um bem que apenas presta serviços gratuitos à população sem gerar entrada de caixa não pode ser classificado como Ativo.', exp: 'No setor público, o recurso caracteriza-se pelo POTENCIAL DE SERVIÇOS ou pela capacidade de gerar benefícios econômicos.' },
    { sub: 'Outros Recursos e Outras Obrigações (Diferimento no Balanço)', ref: 'NBC TSP Estrutura Conceitual, Cap. 5', t: 'Os elementos definidos na NBC TSP Estrutura Conceitual são: Ativo, Passivo, Receita (VPA), Despesa (VPD), Contribuição dos Proprietários e Distribuição aos Proprietários; além disso, em casos específicos determinados por outras normas, podem ser reconhecidos "Outros Recursos" e "Outras Obrigações" que não atendem à definição de ativo/passivo para assegurar a representação fidedigna do resultado.', f: 'A NBC TSP Estrutura Conceitual define as Contas de Compensação como o sétimo elemento patrimonial obrigatório da DVP.', exp: 'Os 6 elementos patrimoniais na NBC TSP EC são: Ativo, Passivo, Receita (VPA), Despesa (VPD), Contribuição dos Proprietários e Distribuição aos Proprietários.' },
    { sub: 'Bases de Mensuração de Ativos e Passivos na NBC TSP EC', ref: 'NBC TSP Estrutura Conceitual, Cap. 7', t: 'Para os ativos, a NBC TSP Estrutura Conceitual estabelece como bases de mensuração o Custo Histórico e os Valores Correntes: Valor de Mercado, Custo de Reposição (ou Substituição), Preço Líquido de Venda e Valor em Uso ( salientando que Valor Justo não consta como base na EC, embora apareça nas demais NBC TSPs).', f: 'Para os passivos, a única base de mensuração admitida pela NBC TSP Estrutura Conceitual é o Preço Líquido de Venda.', exp: 'Bases de Ativo na NBC TSP EC: Custo Histórico, Valor de Mercado, Custo de Reposição, Preço Líquido de Venda, Valor em Uso. Bases de Passivo: Custo Histórico, Custo de Cumprimento da Obrigação, Valor de Mercado, Preço Presumido e Preço de Assunção.' }
  ],
  12: [
    { sub: 'Conceito de Receita Corrente Líquida (RCL)', ref: 'LC 101/2000 (LRF), Art. 2º, IV', t: 'A Receita Corrente Líquida (RCL) corresponde ao somatório das receitas correntes (tributárias, de contribuições, patrimoniais, industriais, agropecuárias, de serviços, transferências correntes e outras) arrecadadas no mês em referência e nos onze anteriores (12 meses), excluídas as duplicidades e as deduções legais (transferências constitucionais, contribuição dos servidores ao RPPS, compensação financeira entre regimes e deduções para o Fundeb).', f: 'As receitas de capital provenientes de alienação de bens imóveis e operações de crédito integram o cálculo da Receita Corrente Líquida.', exp: 'A RCL é apurada no período móvel de 12 meses (mês de referência + 11 anteriores) considerando apenas Receitas Correntes menos deduções legais.' },
    { sub: 'Limites Globais de Despesa Total com Pessoal na LRF', ref: 'LC 101/2000 (LRF), Art. 19', t: 'A despesa total com pessoal, em cada período de apuração e em cada ente da Federação, não poderá exceder os seguintes percentuais da Receita Corrente Líquida (RCL): União = 50%; Estados = 60%; e Municípios = 60%.', f: 'Pela Lei de Responsabilidade Fiscal, o limite global de despesa com pessoal para os Estados é de 50% da RCL e para a União é de 60%.', exp: 'União = 50% da RCL; Estados = 60% da RCL; Municípios = 60% da RCL.' },
    { sub: 'Repartição do Limite de Pessoal nos Estados (Art. 20, II da LRF)', ref: 'LC 101/2000 (LRF), Art. 20, II', t: 'Na esfera estadual, o limite de 60% da RCL reparte-se em: 3% para o Legislativo (incluído o Tribunal de Contas do Estado), 6% para o Judiciário, 49% para o Executivo e 2% para o Ministério Público dos Estados.', f: 'Nos Estados, o Poder Executivo dispõe de 54% da RCL para gastos com pessoal e o Poder Judiciário dispõe de apenas 2%.', exp: 'Nos Estados (soma = 60%): Executivo = 49%; Judiciário = 6%; Legislativo + TCE = 3%; Ministério Público = 2%. (Nos Municípios: Executivo = 54% e Legislativo = 6%).' },
    { sub: 'Itens Excluídos do Limite de Despesa com Pessoal', ref: 'LC 101/2000 (LRF), Art. 19, §1º', t: 'Na verificação do atendimento dos limites de pessoal, NÃO são computadas as despesas: de indenização por demissão de servidores ou empregados; relativas a incentivos à demissão voluntária; decorrentes de decisão judicial da competência de período anterior ao da apuração; e com inativos e pensionistas custeadas com recursos próprios vinculados ao RPPS (contribuições dos segurados e compensação financeira).', f: 'As verbas de caráter indenizatório (como diárias e auxílio-alimentação) e as indenizações por demissão integram o limite prudencial de pessoal.', exp: 'Indenizações por demissão, PDV, sentenças de períodos anteriores e inativos pagos com recursos próprios do RPPS são deduções da despesa bruta com pessoal.' },
    { sub: 'Limite de Alerta (90%), Limite Prudencial (95%) e Excesso Total (100%)', ref: 'LC 101/2000 (LRF), Arts. 22, 23 e 59', t: 'O Tribunal de Contas alerta o Poder/órgão quando a despesa com pessoal ultrapassa 90% do limite; ao ultrapassar 95% (limite prudencial), ficam vedados concessão de vantagem/aumento, criação de cargo, alteração de carreira e contratação de hora extra (salvo LDO); e se ultrapassar 100%, o excedente deve ser eliminado nos dois quadrimestres seguintes (sendo pelo menos 1/3 no primeiro).', f: 'Ao atingir 90% do limite de pessoal (limite de alerta), o ente já fica proibido de receber transferências voluntárias da União.', exp: '90% = Alerta do TC; 95% = Limite Prudencial (vedações do Art. 22, par. único); >100% = recondução em 2 quadrimestres (1/3 no 1º).' }
  ],
  13: [
    { sub: 'Regra de Ouro (Art. 167, III da CF/88 e Art. 12, §2º da LRF)', ref: 'CF/88, Art. 167, III e LRF', t: 'Pela Regra de Ouro das finanças públicas, é vedada a realização de operações de créditos que excedam o montante das despesas de capital, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta.', f: 'A Regra de Ouro proíbe qualquer contratação de empréstimo externo para financiar obras de infraestrutura rodoviária.', exp: 'O objetivo da Regra de Ouro é impedir que o Estado se endivide (Operação de Crédito - Receita de Capital) para pagar Despesas Correntes (pessoal, custeio, juros).' },
    { sub: 'Operação de Crédito por Antecipação de Receita Orçamentária (ARO)', ref: 'LC 101/2000 (LRF), Art. 38', t: 'A operação de crédito por Antecipação de Receita Orçamentária (ARO) destina-se a atender insuficiência de caixa durante o exercício, só pode ser realizada a partir do décimo dia do início do exercício, deve ser liquidada até 10 de dezembro de cada ano e é expressamente proibida no último ano de mandato do Chefe do Poder Executivo.', f: 'A operação de ARO é classificada como Receita Orçamentária Corrente e pode ser contratada no último ano de mandato desde que paga até 31 de dezembro.', exp: 'A ARO é ingresso extraorçamentário (Lei 4.320/64, Art. 3º, par. único) que só pode ser contratada a partir de 10/jan, liquidada até 10/dez e vedada no último ano de mandato.' },
    { sub: 'Relatório Resumido da Execução Orçamentária (RREO) vs. Relatório de Gestão Fiscal (RGF)', ref: 'LC 101/2000 (LRF), Arts. 52 a 55', t: 'O RREO é elaborado e publicado exclusivamente pelo Poder Executivo (abrangendo todos os Poderes) até 30 dias após o encerramento de cada BIMESTRE; já o RGF é emitido separadamente pelos titulares de cada Poder e órgão autônomo ao final de cada QUADRIMESTRE (até 30 dias após).', f: 'O Relatório Resumido da Execução Orçamentária (RREO) é publicado quadrimestralmente por cada Poder de forma isolada.', exp: 'RREO = Bimestral, pelo Executivo (consolidado de todos os Poderes); RGF = Quadrimestral, por cada Poder/órgão (despesa com pessoal, dívida, garantias, ARO).' },
    { sub: 'Restrição de Final de Mandato: Restos a Pagar (Art. 42 da LRF)', ref: 'LC 101/2000 (LRF), Art. 42', t: 'Nos últimos dois quadrimestres do seu mandato (últimos 8 meses), é vedado ao titular de Poder ou órgão contrair obrigação de despesa que não possa ser cumprida integralmente dentro dele, ou que tenha parcelas a serem pagas no exercício seguinte sem que haja suficiente disponibilidade de caixa para este efeito.', f: 'O Art. 42 da LRF proíbe a inscrição de Restos a Pagar apenas nos últimos trinta dias do primeiro ano de mandato.', exp: 'Art. 42 da LRF = últimos 2 quadrimestres (maio a dezembro do último ano de mandato): toda obrigação nova deixada para o ano seguinte exige disponibilidade líquida de caixa.' },
    { sub: 'Renúncia de Receita (Art. 14 da LRF)', ref: 'LC 101/2000 (LRF), Art. 14', t: 'A concessão ou ampliação de incentivo ou benefício de natureza tributária da qual decorra renúncia de receita deverá estar acompanhada de estimativa do impacto orçamentário-financeiro no exercício e nos dois seguintes, atender à LDO e a pelo menos uma de duas condições (demonstração de que foi considerada na LOA sem afetar as metas, ou medidas de compensação por aumento de receita), excetuando-se alterações de II, IE, IPI e IOF e cancelamento de débito de pequeno valor.', f: 'Qualquer redução de alíquota do IOF ou do Imposto de Importação pelo Poder Executivo exige prévia compensação tributária nos termos do Art. 14 da LRF.', exp: 'Os impostos regulatórios federais (II, IE, IPI e IOF) e o cancelamento de débito cujo montante seja inferior ao dos respectivos custos de cobrança estão dispensados das exigências do Art. 14 da LRF (§3º).' }
  ],
  14: [
    { sub: 'Princípio da Universalidade vs. Princípio da Exclusividade', ref: 'CF/88, Art. 165, §§ 5º e 8º e Lei 4.320/64, Arts. 2º a 4º', t: 'Pelo princípio da Universalidade, a LOA deve conter todas as receitas e todas as despesas de todos os Poderes, órgãos, fundos e entidades; já pelo princípio da Exclusividade, a LOA não conterá dispositivo estranho à previsão da receita e à fixação da despesa, ressalvadas a autorização para abertura de créditos suplementares e a contratação de operações de crédito, ainda que por ARO.', f: 'O princípio da exclusividade permite a inclusão de normas de direito penal e trabalhista no texto da Lei Orçamentária Anual.', exp: 'As duas únicas exceções constitucionais ao princípio da Exclusividade (caudas orçamentárias vedadas) são: (1) autorização para créditos suplementares; e (2) operações de crédito (inclusive ARO).' },
    { sub: 'Princípio do Orçamento Bruto', ref: 'Lei 4.320/64, Art. 6º', t: 'Pelo princípio do Orçamento Bruto, todas as receitas e despesas constarão da Lei de Orçamento pelos seus totais, vedadas quaisquer deduções (ex: o IRRF retido sobre a folha de servidores figura pelo bruto na despesa de pessoal e simultaneamente na receita tributária).', f: 'Pelo princípio do orçamento bruto, a receita de ICMS do Estado já entra na LOA deduzida dos 25% pertencentes aos Municípios.', exp: 'Art. 6º da Lei 4.320/64: o ICMS entra 100% na Receita do Estado e os 25% dos Municípios constam como Despesa de Transferência Constitucional.' },
    { sub: 'Princípio da Não Afetação (Não Vinculação) da Receita de Impostos', ref: 'CF/88, Art. 167, IV', t: 'É vedada a vinculação de receita de IMPOSTOS a órgão, fundo ou despesa, ressalvadas as exceções constitucionais expressas: repartição constitucional de receitas, saúde e educação (ASPS e MDE), atividades da administração tributária, e prestação de garantias/contragarantias às operações de crédito por ARO e débitos com a União.', f: 'O princípio da não afetação do Art. 167, IV da CF/88 proíbe a vinculação de taxas e contribuições especiais a fundos específicos.', exp: 'Atenção: o princípio da não afetação restringe-se exclusivamente aos IMPOSTOS (taxas e contribuições já nascem vinculadas).' },
    { sub: 'Princípio da Anualidade (Periodicidade) e Reabertura de Créditos', ref: 'Lei 4.320/64, Art. 34 e CF/88, Art. 167, §2º', t: 'No Brasil, o exercício financeiro coincide com o ano civil (1º de janeiro a 31 de dezembro); como exceção ao princípio da anualidade, os créditos especiais e extraordinários cujo ato de autorização for promulgado nos últimos quatro meses do exercício (setembro a dezembro) poderão ser reabertos nos limites de seus saldos no exercício seguinte.', f: 'Os créditos suplementares abertos em qualquer mês do ano são automaticamente reabertos para os três exercícios seguintes.', exp: 'Apenas créditos ESPECIAIS e EXTRAORDINÁRIOS abertos nos últimos 4 meses do exercício podem ser reabertos (créditos suplementares nunca são reabertos).' },
    { sub: 'Princípio da Unidade (Totalidade) e as Três Esferas da LOA', ref: 'CF/88, Art. 165, §5º', t: 'Pelo princípio da Unidade (ou Totalidade), o orçamento deve ser uno em cada ente federado, embora a LOA seja formalmente estruturada em três suborçamentos integrados: o Orçamento Fiscal, o Orçamento de Investimento das Empresas Estatais (independentes) e o Orçamento da Seguridade Social.', f: 'As despesas com pessoal do Ministério da Saúde integram o Orçamento de Investimento das Empresas Estatais.', exp: 'A LOA é uma peça única dividida em 3 esferas: Fiscal (F), Seguridade Social (S) e Investimento das Estatais não dependentes (I).' }
  ],
  15: [
    { sub: 'Conceito e Classificação Civil dos Bens Públicos', ref: 'Código Civil, Art. 99 e MCASP', t: 'Quanto à destinação jurídica (Art. 99 do Código Civil), os bens públicos dividem-se em: (1) Bens de Uso Comum do Povo (rios, mares, estradas, ruas e praças); (2) Bens de Uso Especial (edifícios ou terrenos aplicados a serviço ou estabelecimento da administração, como escolas, hospitais e repartições); e (3) Bens Dominicais (patrimônio disponível sem destinação pública específica).', f: 'Os bens de uso comum do povo e os bens de uso especial podem ser livremente penhorados e adquiridos por usucapião.', exp: 'Todos os bens públicos são impenhoráveis e imprescritíveis (vedado usucapião, Art. 183, §3º da CF/88); os de uso comum e especial são também inalienáveis enquanto afetados.' },
    { sub: 'Afetação e Desafetação de Bens Públicos', ref: 'Direito Administrativo / CASP', t: 'A afetação é a consagração de um bem a uma finalidade pública específica (uso comum ou uso especial), tornando-o inalienável; a desafetação retira essa destinação pública e transfere o bem para a categoria de bem dominical, permitindo sua alienação nos termos da lei.', f: 'Os bens dominicais são absolutamente inalienáveis mesmo após autorização legislativa e avaliação prévia.', exp: 'Bens dominicais podem ser alienados (observados interesse público, avaliação, licitação e, para imóveis, autorização legislativa), respeitada a vedação do Art. 44 da LRF (aplicar a receita de capital em despesa corrente).' },
    { sub: 'Vedação de Aplicação da Receita de Alienação de Bens (Art. 44 da LRF)', ref: 'LC 101/2000 (LRF), Art. 44', t: 'É vedada a aplicação da receita de capital derivada da alienação de bens e direitos que integram o patrimônio público para o financiamento de despesa corrente, salvo se destinada por lei aos regimes de previdência social, geral e próprio dos servidores públicos.', f: 'O produto da venda de imóveis públicos pode ser livremente utilizado para pagar a folha salarial dos servidores ativos da administração direta.', exp: 'Art. 44 da LRF: Receita de alienação de bens (Receita de Capital) NÃO pode financiar despesa corrente, com uma única exceção: aporte por lei ao RGPS ou RPPS!' },
    { sub: 'Classificação Contábil do Patrimônio Público no PCASP', ref: 'MCASP', t: 'Na contabilidade patrimonial pública, tanto os bens de uso especial (edifícios administrativos, veículos, equipamentos) quanto os bens de uso comum do povo (infraestrutura rodoviária, praças) e os bens dominicais de uso operacional/sem destinação integram o Ativo Não Circulante (Imobilizado ou Investimentos).', f: 'Apenas os bens dominicais são escriturados na Classe 1 (Ativo) do PCASP, ficando os bens de uso especial fora do balanço.', exp: 'O Balanço Patrimonial público registra todos os bens controlados pelo ente: uso especial, uso comum (infraestrutura) e dominicais.' },
    { sub: 'Depreciação e Reavaliação na Composição do Patrimônio Público', ref: 'NBC TSP 07 e MCASP', t: 'Os bens integrantes do Ativo Imobilizado público (exceto terrenos e bens culturais de vida útil indefinida) estão sujeitos ao registro mensal de depreciação pelo regime de competência (VPD na Classe 3 contra Depreciação Acumulada retificadora na Classe 1).', f: 'Na contabilidade pública, a depreciação é calculada apenas no momento da baixa definitiva do bem por sucateamento.', exp: 'A depreciação no setor público é mensal e sistemática ao longo da vida útil econômica do bem.' }
  ],
  16: [
    { sub: 'Mensuração de Estoques Comercializáveis vs. para Distribuição Gratuita', ref: 'NBC TSP 04 e MCASP', t: 'Segundo a NBC TSP 04 (Estoques), os estoques em geral são mensurados pelo menor valor entre o custo e o valor realizável líquido; contudo, os estoques mantidos para distribuição gratuita ou por valor irrisório (ex: medicamentos do SUS, livros didáticos) ou para consumo na prestação gratuita de serviços públicos devem ser mensurados pelo menor valor entre o custo e o CUSTO CORRENTE DE REPOSIÇÃO.', f: 'Os medicamentos mantidos pelo Estado para distribuição gratuita nos postos de saúde são mensurados exclusivamente pelo preço de venda no varejo farmacêutico.', exp: 'Regra de ouro da NBC TSP 04: Estoques para distribuição gratuita / consumo gratuito -> menor entre Custo e Custo Corrente de Reposição!' },
    { sub: 'Estoques Obtidos em Transação Sem Contraprestação (Doação)', ref: 'NBC TSP 04, item 16', t: 'Quando os estoques são adquiridos por meio de uma transação sem contraprestação (como cestas básicas ou vacinas recebidas em doação), o seu custo no reconhecimento inicial deve ser mensurado pelo seu valor justo na data do recebimento.', f: 'Estoques recebidos gratuitamente por doação não são registrados no Ativo Circulante do órgão público.', exp: 'Recebimento de estoque em doação: D - Estoques (Ativo Circulante, pelo Valor Justo) / C - VPA Transferências/Doações Recebidas.' },
    { sub: 'Critérios de Valoração de Estoques no Setor Público (Média Ponderada e PEPS)', ref: 'Lei 4.320/64, Art. 106, III e NBC TSP 04', t: 'Embora a NBC TSP 04 mencione o PEPS e o custo médio ponderado (vedando o UEPS), o MCASP determina que, para atender simultaneamente ao Art. 106, III da Lei 4.320/64, os órgãos e entidades do setor público brasileiro utilizem como regra o método do Preço Médio Ponderado.', f: 'O MCASP obriga todas as prefeituras e secretarias estaduais a avaliarem seus almoxarifados pelo método UEPS.', exp: 'Para harmonizar a NBC TSP 04 com o Art. 106, III da Lei 4.320/64, o MCASP adota o Preço Médio Ponderado para os estoques públicos.' },
    { sub: 'Reconhecimento do Consumo de Estoques como VPD', ref: 'NBC TSP 04 e MCASP', t: 'Quando os estoques de almoxarifado são requisitados para consumo interno ou distribuídos gratuitamente à população, o valor contábil desses itens deve ser baixado do Ativo Circulante e reconhecido como Variação Patrimonial Diminutiva (VPD - Uso de Material de Consumo ou Material de Distribuição Gratuita) no período da entrega/consumo.', f: 'No setor público, a VPD de material de consumo é reconhecida integralmente no momento da emissão da nota de empenho, mesmo antes da entrega pelo fornecedor.', exp: 'Na compra e entrada no almoxarifado, o fato é permutativo (entra Estoque, cria Passivo); a VPD só ocorre na requisição/consumo ou distribuição!' },
    { sub: 'Distinção entre Material de Consumo (Estoque) e Material Permanente (Imobilizado)', ref: 'MCASP', t: 'Para a classificação contábil e orçamentária entre material de consumo (Estoque) e material permanente (Imobilizado), o MCASP adota o critério da durabilidade (em regra, material de consumo perde sua identidade física ou tem durabilidade limitada a 2 anos), conjugado com os parâmetros excludentes de fragilidade, perecibilidade, incorporabilidade e transformabilidade.', f: 'Uma peça de reposição que será incorporada definitivamente ao motor de um veículo é classificada como equipamento permanente autônomo.', exp: 'Pelos 5 parâmetros excludentes do MCASP (Durabilidade <= 2 anos, Fragilidade, Perecibilidade, Incorporabilidade e Transformabilidade), se atender a qualquer um deles, classifica-se como Material de Consumo.' }
  ],
  17: [
    { sub: 'Natureza Contábil do Fundeb (Fundo de Natureza Contábil Estadual/Distrital)', ref: 'CF/88, Art. 212-A, Lei 14.113/2020 e MCASP', t: 'O Fundo de Manutenção e Desenvolvimento da Educação Básica e de Valorização dos Profissionais da Educação (Fundeb), tornado permanente pela EC 108/2020, é um fundo de natureza contábil instituído no âmbito de cada Estado e do Distrito Federal, alimentado por 20% da cesta de impostos e transferências estaduais e municipais, além da complementação da União.', f: 'O Fundeb é uma autarquia federal com personalidade jurídica própria que retém apenas 5% do ICMS.', exp: 'Os Estados e Municípios contribuem com 20% das receitas da cesta do Fundeb (ICMS, IPVA, ITCMD, FPE, FPM, ITR-cota, IPI-Exp, etc.), acrescidos da complementação da União (VAAT, VAAF, VAAR).' },
    { sub: 'Contabilização da Retenção para Formação do Fundeb (Dedução da Receita)', ref: 'MCASP - Parte I e Parte V', t: 'Os valores retidos automaticamente das receitas de impostos e transferências de Estados e Municípios para a formação do Fundeb são registrados como Dedução da Receita Orçamentária (código redutor 9.5) sob o enfoque orçamentário e como VPD de Transferências sob o enfoque patrimonial.', f: 'O desconto de 20% na cota-parte do FPM ou do ICMS para formação do Fundeb deve ser empenhado pelo Município como Despesa Corrente de Pessoal.', exp: 'A contribuição ao Fundeb NÃO é despesa orçamentária empenhada: é contabilizada como Dedução da Receita Orçamentária (redutora da receita)!' },
    { sub: 'Contabilização dos Recursos Recebidos do Fundeb (Transferência Corrente)', ref: 'MCASP', t: 'Os recursos financeiros efetivamente recebidos pelos Estados e Municípios da conta do Fundeb (com base no número de alunos matriculados na respectiva rede de ensino) são registrados como Receita Orçamentária de Transferências Correntes (1.7.5.1.x) e como VPA de Transferências Intergovernamentais.', f: 'O retorno dos recursos do Fundeb para a conta do Município classifica-se como Operação de Crédito Interna.', exp: 'Contribuição ao Fundeb = Dedução da Receita; Retorno/Recebimento do Fundeb (e Complementação da União) = Receita Corrente de Transferências.' },
    { sub: 'Ganho ou Perda Líquida com o Fundeb', ref: 'MCASP', t: 'Confrontando-se o valor recebido do Fundeb (Receita de Transferências do Fundeb, excluída a complementação da União) com o valor retido para formação do Fundo (Dedução da Receita), o ente apura se teve ganho líquido (acréscimo) ou perda líquida (decréscimo) na redistribuição estadual.', f: 'Todos os Municípios e Estados recebem de volta do Fundeb exatamente o mesmo valor nominal que contribuíram.', exp: 'Como a distribuição segue o número de matrículas ponderadas, alguns entes são recebedores líquidos (ganho) e outros são contribuintes líquidos (perda).' },
    { sub: 'Mínimo Constitucional de 70% do Fundeb para Profissionais da Educação Básica', ref: 'CF/88, Art. 212-A, XI e Lei 14.113/2020', t: 'Proporção não inferior a 70% (setenta por cento) dos recursos anuais totais dos Fundos (excluídos os recursos da complementação-VAAR de capital) será destinada ao pagamento dos profissionais da educação básica em efetivo exercício.', f: 'A Constituição Federal permite utilizar 80% dos recursos do Fundeb para pagamento de aposentadorias e pensões de servidores inativos.', exp: 'Desde a EC 108/2020, o piso de remuneração dos profissionais da educação básica em efetivo exercício subiu de 60% para 70% do Fundeb (vedado pagar inativos com o Fundeb).' }
  ],
  18: [
    { sub: 'Síntese FGV: Regime Orçamentário vs. Regime Patrimonial na CASP', ref: 'Revisão Geral CASP FGV', t: 'Sob a ótica orçamentária (Art. 35 da Lei 4.320/64), as receitas seguem o regime de caixa (arrecadação) e as despesas seguem o empenho; sob a ótica patrimonial (MCASP e NBC TSP), as Variações Patrimoniais Aumentativas (VPA) e Diminutivas (VPD) são reconhecidas estritamente pelo regime de competência (na ocorrência do fato gerador).', f: 'Com a convergência internacional às normas IPSAS, o Art. 35 da Lei 4.320/64 foi revogado e a receita orçamentária passou a ser registrada no lançamento.', exp: 'Os dois regimes convivem em harmonia porque utilizam classes distintas do PCASP (Classes 1 a 4 para o regime patrimonial de competência; Classes 5 e 6 para o regime orçamentário).' },
    { sub: 'Síntese FGV: Classificação das 8 Classes do PCASP e Atributos F/P', ref: 'Revisão Geral CASP FGV', t: 'No PCASP, as Classes 1, 2, 3 e 4 compõem a natureza de informação Patrimonial (sendo que Ativo e Passivo recebem os atributos F para Financeiro e P para Permanente); as Classes 5 e 6 compõem a natureza Orçamentária; e as Classes 7 e 8 compõem a natureza de Controle.', f: 'As Variações Patrimoniais Diminutivas pertencem à Classe 5 do PCASP e as Variações Patrimoniais Aumentativas pertencem à Classe 6.', exp: 'Memorização essencial: 1=Ativo, 2=Passivo/PL, 3=VPD, 4=VPA, 5=Aprovação do Orçamento, 6=Execução do Orçamento, 7=Controles Devedores, 8=Controles Credores.' },
    { sub: 'Síntese FGV: Confronto das Demonstrações Contábeis Públicas (DCASP)', ref: 'Revisão Geral CASP FGV', t: 'O Balanço Orçamentário apura o Resultado Orçamentário (Receita Arrecadada - Despesa Empenhada); o Balanço Financeiro apura a variação do saldo em espécie (incluindo os RP inscritos como ingresso extraorçamentário); o Balanço Patrimonial apura o Patrimônio Líquido e o Superávit Financeiro (AF - PF); e a DVP apura o Resultado Patrimonial (VPA - VPD).', f: 'O Superávit Financeiro que serve de fonte para créditos adicionais é apurado na Demonstração das Variações Patrimoniais (DVP).', exp: 'Superávit Orçamentário = no BO; Resultado Financeiro do Exercício = no BF; Superávit Financeiro (AF - PF) = no BP; Superávit Patrimonial (VPA - VPD) = na DVP.' },
    { sub: 'Síntese FGV: Reavaliação, Estoques Gratuitos e Características Qualitativas', ref: 'Revisão Geral CASP FGV', t: 'Na CASP: (1) a reavaliação de ativos imobilizados e intangíveis a valor justo é permitida; (2) os estoques para distribuição gratuita são mensurados pelo menor valor entre o custo e o custo corrente de reposição; e (3) a NBC TSP Estrutura Conceitual estabelece 6 características qualitativas (Relevância, Representação Fidedigna, Compreensibilidade, Tempestividade, Comparabilidade e Verificabilidade) e 3 restrições (Materialidade, Custo-Benefício e Equilíbrio).', f: 'Na CASP, a reavaliação de ativos é proibida e os estoques para distribuição gratuita são avaliados pelo valor realizável líquido de venda.', exp: 'Estes três pontos diferenciam a CASP (NBC TSP) da Contabilidade Societária (CPC) e são os mais cobrados pela FGV!' },
    { sub: 'Síntese FGV: Limites da LRF e Contabilização do Fundeb', ref: 'Revisão Geral CASP FGV', t: 'Na LRF, o limite global de despesa com pessoal é de 50% da RCL na União e 60% nos Estados (49% Executivo, 6% Judiciário, 3% Legislativo/TCE, 2% MP) e Municípios (54% Executivo, 6% Legislativo); já no Fundeb, a retenção de 20% da cesta de impostos é contabilizada como Dedução da Receita Orçamentária.', f: 'A retenção de 20% do ICMS para formação do Fundeb é empenhada como despesa de capital na função Educação.', exp: 'Resumo de ouro para a prova da SEFAZ-BA: limites estaduais da LRF (49/6/3/2 = 60%) e Fundeb (retenção = dedução da receita; mínimo de 70% para profissionais da educação básica).' }
  ]
};
